/* Original bilingual enrichment. Loaded after lessons.js as a classic script. */
const CORE_B = [
  {
    id:16, module:4, model:'dns',
    title:{en:'DNS resolution & caching',ta:'DNS பெயர் தீர்மானமும் caching செயல்பாடும்'},
    summary:{en:'Trace a lookup through delegation, recursive resolution, and positive or negative caches.',ta:'ஒரு பெயருக்கான தேடல் delegation வழியாகச் சென்று recursive resolver மூலம் விடை பெறுவதையும், கிடைத்த அல்லது கிடைக்காத விடைகள் cache செய்யப்படுவதையும் ஆராயுங்கள்.'},
    prerequisites:{en:'Understand IP addresses, UDP and TCP ports, and the difference between a hostname and a URL.',ta:'IP address, UDP மற்றும் TCP port ஆகியவற்றையும் hostname என்பது முழு URL அல்ல என்பதையும் புரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Distinguish recursive service from authoritative answers.','Calculate remaining cache lifetime.','Separate NXDOMAIN, NODATA, and resolver failure.'],ta:['Recursive சேவையையும் authoritative விடையையும் வேறுபடுத்துதல்.','Cache-இல் மீதமுள்ள வாழ்நேரத்தைக் கணக்கிடுதல்.','NXDOMAIN, NODATA, resolver failure ஆகியவற்றைத் தனித்தனியாகக் கண்டறிதல்.']},
    sections:[
      {heading:{en:'Hierarchy and delegation',ta:'படிநிலையும் delegation முறையும்'},body:{en:'A stub resolver normally asks a configured recursive resolver for a name and record type. On a cache miss, that resolver can follow referrals from the root to a top-level domain and then to the authoritative zone. Delegation identifies the next servers to ask; it does not mean the root holds every host address. An authoritative server answers for its zone, while a recursive resolver combines cached information and further queries on the client’s behalf.',ta:'Stub resolver பொதுவாக அமைக்கப்பட்ட recursive resolver-இடம் பெயரையும் record வகையையும் குறிப்பிட்டுக் கேட்கிறது. Cache-இல் விடை இல்லாவிட்டால் resolver, root-இலிருந்து top-level domain வழியாக authoritative zone வரை referrals-ஐப் பின்பற்றலாம். Delegation அடுத்ததாக எந்த server-ஐக் கேட்க வேண்டும் என்பதைக் கூறுகிறது; உலகின் எல்லா host address-களும் root-இல் இருப்பதாக இதற்குப் பொருள் இல்லை. Authoritative server தனது zone-க்காக விடை அளிக்கிறது. Recursive resolver பயனருக்காக cache தகவலையும் புதிய queries-ஐயும் இணைக்கிறது.'}},
      {heading:{en:'Records and cache lifetimes',ta:'Records மற்றும் cache வாழ்நேரம்'},body:{en:'A and AAAA records supply IPv4 and IPv6 addresses; MX identifies mail exchangers, and CNAME points to another name. TTL limits how long cached information may be reused without refreshing it. Different record sets along an alias chain can expire at different times. Applications and operating systems may add their own caching layers, so inspecting one resolver does not reveal every cached copy. Lowering a TTL after an old answer was cached does not retroactively shorten that copy’s original lifetime.',ta:'A record IPv4 address-ஐயும் AAAA record IPv6 address-ஐயும் தருகின்றன. MX mail exchanger-ஐக் குறிப்பிடுகிறது; CNAME மற்றொரு பெயரைச் சுட்டுகிறது. புதுப்பிக்காமல் ஒரு cache விடையை எவ்வளவு காலம் மீண்டும் பயன்படுத்தலாம் என்பதை TTL வரையறுக்கிறது. Alias தொடரிலுள்ள record தொகுதிகள் வெவ்வேறு நேரங்களில் காலாவதியாகலாம். Application மற்றும் operating system தனி cache வைத்திருக்கலாம்; ஒரு resolver-ஐ மட்டும் பார்ப்பதால் எல்லா நகல்களும் தெரியாது. பழைய விடை cache செய்யப்பட்ட பிறகு TTL-ஐக் குறைத்தால் அந்த நகலின் பழைய வாழ்நேரம் உடனடியாகக் குறையாது.'}},
      {heading:{en:'Negative answers and trust',ta:'எதிர்மறை விடைகளும் நம்பகத்தன்மையும்'},body:{en:'NXDOMAIN means the queried name does not exist; NODATA means the name exists but the requested record type has no answer. Negative caching uses zone SOA information under defined rules. SERVFAIL indicates resolution failure rather than proof of absence. DNSSEC authenticates signed DNS data through a trust chain, but does not encrypt queries or certify that a website is harmless. DNS over TLS or HTTPS protects the resolver transport; the chosen resolver still sees the question.',ta:'NXDOMAIN என்பது கேட்ட பெயர் இல்லை என்பதைக் குறிக்கும். NODATA என்பது பெயர் இருந்தாலும் கேட்ட record வகைக்கான விடை இல்லை என்பதாகும். வரையறுக்கப்பட்ட விதிகளின்படி zone SOA தகவலைப் பயன்படுத்தி negative விடைகள் cache செய்யப்படுகின்றன. SERVFAIL என்பது தீர்மானிக்க முடியாத நிலை; பெயர் இல்லை என்பதற்கான ஆதாரம் அல்ல. DNSSEC கையொப்பமிட்ட DNS தகவலை trust chain வழியாகச் சரிபார்க்கிறது; query-ஐ encrypt செய்வதோ website தீங்கற்றது என்று உறுதி செய்வதோ இல்லை. DNS over TLS அல்லது HTTPS resolver வரை செல்லும் தொடர்பைப் பாதுகாக்கிறது; தேர்ந்தெடுத்த resolver கேள்வியைப் பார்க்க முடியும்.'}}
    ],
    example:{en:'A resolver caches an A record with TTL 300 at 12:00:00. At 12:01:20, 80 seconds have elapsed, leaving approximately 220 seconds. A second client can use this cached answer without contacting the authority. An independently cached AAAA answer may have a different expiry.',ta:'12:00:00 மணிக்கு TTL 300 கொண்ட A record cache செய்யப்படுகிறது. 12:01:20 மணிக்கு 80 வினாடிகள் கடந்ததால் சுமார் 220 வினாடிகள் மீதமிருக்கும். இரண்டாவது client authoritative server-ஐ மீண்டும் அணுகாமல் இதைப் பெறலாம். தனியாக cache செய்யப்பட்ட AAAA விடையின் காலாவதி நேரம் வேறாக இருக்கலாம்.'},
    failure:{en:'A newly created name still returns NXDOMAIN from one resolver. Check its negative-cache lifetime and query the authoritative server before editing the zone repeatedly. If the response is SERVFAIL instead, investigate validation, delegation, and upstream reachability rather than assuming the record is missing.',ta:'புதிதாக உருவாக்கிய பெயருக்கு ஒரு resolver இன்னும் NXDOMAIN தருகிறது. Zone-ஐ மீண்டும் மீண்டும் மாற்றுவதற்கு முன் negative-cache வாழ்நேரத்தைப் பார்த்து authoritative server-இடம் கேளுங்கள். SERVFAIL வந்தால் record இல்லை என்று முடிவெடுக்காமல் validation, delegation, upstream தொடர்பு ஆகியவற்றை ஆராயுங்கள்.'},
    lab:{commands:'dig example.com A\ndig example.com A\ndig example.com AAAA\ndig example.com SOA\ndig example.com A +tcp',guidance:{en:'Use dig from the DNS utilities package. Compare status, responding server, TTL, and query time across repeated requests. These commands contact your configured resolver; they do not flush caches or modify DNS. TCP queries demonstrate that DNS is not restricted to UDP.',ta:'DNS utilities தொகுப்பிலுள்ள dig தேவை. மீண்டும் கேட்கும்போது status, விடையளித்த server, TTL, query நேரம் ஆகியவற்றை ஒப்பிடுங்கள். இவை அமைக்கப்பட்ட resolver-ஐ அணுகும்; cache-ஐ அழிக்கவோ DNS-ஐ மாற்றவோ செய்யாது. DNS, UDP மட்டும் பயன்படுத்துவதில்லை என்பதை TCP query காட்டும்.'},expected:{en:'Successful queries show NOERROR and relevant records. TTL often decreases on repeated answers, but cache pools, refreshes, or policy can change the observation; a faster second query alone does not prove caching.',ta:'வெற்றியான queries-இல் NOERROR மற்றும் பொருத்தமான records தெரியும். மீண்டும் கேட்கும்போது TTL குறையலாம்; cache pool, refresh, policy காரணமாக மாறுபாடும் வரலாம். இரண்டாவது query வேகமாக இருந்தது மட்டும் caching-ஐ நிரூபிக்காது.'},cleanup:{en:'No configuration or persistent lab files were created; no cleanup is required.',ta:'அமைப்போ நிரந்தர lab கோப்புகளோ உருவாக்கப்படவில்லை; அகற்ற வேண்டியது இல்லை.'}},
    questions:[
      {question:{en:'Which server answers from responsibility for a zone?',ta:'ஒரு zone-க்கான பொறுப்பின் அடிப்படையில் எந்த server விடை அளிக்கிறது?'},options:{en:['Authoritative server','Ethernet switch','Any HTTP proxy'],ta:['Authoritative server','Ethernet switch','எந்த HTTP proxy-யும்']},answer:0,explanation:{en:'Authority belongs to the zone’s servers; recursion is a separate service role.',ta:'Zone-இன் server-களுக்கே அதன் அதிகாரப்பூர்வ விடைப் பொறுப்பு உள்ளது; recursion வேறொரு சேவைப் பணி.'}},
      {question:{en:'TTL 600 was cached 150 seconds ago. What lifetime remains without refresh?',ta:'TTL 600 கொண்ட விடை 150 வினாடிகளுக்கு முன் cache செய்யப்பட்டது. Refresh இல்லாமல் எவ்வளவு நேரம் மீதம்?'},options:{en:['450 seconds','750 seconds','150 seconds'],ta:['450 வினாடிகள்','750 வினாடிகள்','150 வினாடிகள்']},answer:0,explanation:{en:'Subtract elapsed time: 600 − 150 = 450 seconds.',ta:'கடந்த நேரத்தைக் கழிக்க வேண்டும்: 600 − 150 = 450 வினாடிகள்.'}},
      {question:{en:'An A query succeeds but an AAAA query returns NODATA. What follows?',ta:'A query வெற்றி; AAAA query-க்கு NODATA. இதிலிருந்து என்ன அறியலாம்?'},options:{en:['The name exists without an AAAA answer','The entire domain does not exist','TLS is invalid'],ta:['பெயர் உள்ளது; AAAA விடை இல்லை','முழு domain-மும் இல்லை','TLS செல்லாது']},answer:0,explanation:{en:'NODATA concerns the requested type, unlike NXDOMAIN’s name error.',ta:'NODATA கேட்ட record வகையைப் பற்றியது; NXDOMAIN போல பெயரே இல்லை என்பதல்ல.'}}
    ],refs:[['DNS concepts — RFC 1034','https://www.rfc-editor.org/rfc/rfc1034.html'],['Negative caching — RFC 2308','https://www.rfc-editor.org/rfc/rfc2308.html'],['Resolution failure caching — RFC 9520','https://www.rfc-editor.org/rfc/rfc9520.html']]
  },
  {
    id:17,module:4,model:'http',title:{en:'HTTP: requests, responses & caching',ta:'HTTP: requests, responses மற்றும் caching'},
    summary:{en:'Connect HTTP methods, status codes, representations, and cache validation to observable exchanges.',ta:'HTTP method, status code, representation, cache validation ஆகியவற்றை நேரில் காணக்கூடிய பரிமாற்றங்களுடன் இணைத்துப் புரிந்துகொள்ளுங்கள்.'},
    prerequisites:{en:'Understand URLs, DNS resolution, and the distinction between transport delivery and application meaning.',ta:'URL, DNS தீர்மானம், transport தரவு வழங்குதல் மற்றும் application பொருள் ஆகியவற்றின் வேறுபாடு தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Interpret method and response semantics.','Distinguish freshness from validation.','Diagnose stale content without treating every response as a download.'],ta:['Method மற்றும் response பொருளை விளக்குதல்.','Freshness மற்றும் validation-ஐ வேறுபடுத்துதல்.','ஒவ்வொரு response-யும் முழு download என்று கருதாமல் பழைய content சிக்கலைக் கண்டறிதல்.']},
    sections:[
      {heading:{en:'Requests express operations',ta:'செயல்களைக் குறிப்பிடும் requests'},body:{en:'HTTP defines application semantics independently of a particular wire version. A request identifies a target, method, fields, and sometimes content. GET retrieves a representation; HEAD requests the corresponding metadata without response content. POST asks the target to process supplied content according to its own rules. Safe means the requested semantics are essentially read-only, not that a request has no logging side effects. Idempotent means repeating the operation has the same intended effect as performing it once.',ta:'ஒரு குறிப்பிட்ட wire version-ஐச் சாராமல் HTTP application பொருளை வரையறுக்கிறது. Request-இல் target, method, fields, சில நேரங்களில் content இருக்கும். GET ஒரு representation-ஐப் பெறுகிறது; HEAD அதற்கான metadata-ஐ response content இல்லாமல் கேட்கிறது. POST கொடுக்கப்பட்ட content-ஐ target-இன் விதிப்படி செயலாக்கச் சொல்கிறது. Safe என்பது கோரிய செயல் அடிப்படையில் வாசிப்புக்கானது என்பதே; log எழுதுவது போன்ற பக்கவிளைவுகள் இல்லை என்பதல்ல. Idempotent என்பது மீண்டும் செய்தாலும் நோக்கமுள்ள விளைவு ஒருமுறை செய்ததைப் போலவே இருப்பதாகும்.'}},
      {heading:{en:'Responses and representations',ta:'Responses மற்றும் representations'},body:{en:'A response carries a status code and fields describing the result. A 200 response commonly supplies the requested representation; 404 reports that the target was not found, while 503 indicates temporary service unavailability. Redirects tell the client about another location and require careful method handling. Content-Type describes media format, whereas Content-Encoding describes an applied encoding such as gzip. A successful TCP connection proves neither successful HTTP authorization nor valid application data; inspect the actual status and content.',ta:'Response-இல் முடிவை விளக்கும் status code மற்றும் fields உள்ளன. 200 பொதுவாகக் கேட்ட representation-ஐத் தருகிறது; 404 target கிடைக்கவில்லை என்கிறது; 503 தற்காலிக சேவை இல்லாமையைக் குறிக்கிறது. Redirect வேறொரு இடத்தைச் சொல்கிறது; method எவ்வாறு தொடர்கிறது என்பதை கவனிக்க வேண்டும். Content-Type ஊடக வடிவத்தைக் குறிப்பிடுகிறது; Content-Encoding, gzip போன்ற பயன்படுத்தப்பட்ட encoding-ஐக் குறிப்பிடுகிறது. TCP connection வெற்றி பெற்றது மட்டும் HTTP அனுமதி அல்லது சரியான application தரவை நிரூபிக்காது; உண்மையான status மற்றும் content-ஐப் பார்க்க வேண்டும்.'}},
      {heading:{en:'Freshness, validators, and privacy',ta:'Freshness, validators மற்றும் தனியுரிமை'},body:{en:'A cache can reuse a fresh stored response when applicable rules permit. Cache-Control max-age gives a freshness lifetime; response age and intermediary handling matter. A stale response can be validated using an ETag with If-None-Match. A 304 response tells the cache to reuse its stored representation with updated metadata. No-cache allows storage but requires validation before reuse; no-store prohibits storage by conforming caches. Vary identifies request fields that influence representation selection, preventing inappropriate reuse across variants.',ta:'பொருந்தும் விதிகள் அனுமதித்தால் fresh நிலையில் சேமிக்கப்பட்ட response-ஐ cache மீண்டும் பயன்படுத்தலாம். Cache-Control max-age freshness வாழ்நேரத்தைத் தருகிறது; response வயதும் இடைநிலை கையாளுதலும் முக்கியம். Stale response-ஐ ETag மற்றும் If-None-Match கொண்டு சரிபார்க்கலாம். 304 வந்தால் புதுப்பிக்கப்பட்ட metadata உடன் சேமித்த representation-ஐ மீண்டும் பயன்படுத்தலாம். No-cache சேமிப்பை அனுமதிக்கும்; மீண்டும் பயன்படுத்துமுன் validation தேவை. No-store விதியைப் பின்பற்றும் cache சேமிக்கக் கூடாது. Representation தேர்வை மாற்றும் request fields-ஐ Vary குறிப்பிடுவதால் தவறான variant பகிர்வு தவிர்க்கப்படுகிறது.'}}
    ],
    example:{en:'A response has max-age=120 and ETag "v7". At age 150 seconds it is stale. The client sends If-None-Match: "v7"; a 304 means the existing body remains usable after metadata updates. If the resource changed, the server can instead send 200 with a new body and validator.',ta:'Response-இல் max-age=120, ETag "v7" உள்ளது. வயது 150 வினாடிகளானால் stale. Client, If-None-Match: "v7" அனுப்புகிறது; 304 வந்தால் metadata புதுப்பித்தபின் பழைய body-ஐப் பயன்படுத்தலாம். Resource மாறியிருந்தால் server புதிய body மற்றும் validator உடன் 200 அனுப்பலாம்.'},
    failure:{en:'A shared cache serves one user’s personalized page to another. Investigate response cache directives, authorization handling, and the cache key rather than merely reducing TTL. Private user content needs an appropriate storage policy; Vary alone is not a universal confidentiality control.',ta:'Shared cache ஒரு பயனரின் தனிப்பயன் பக்கத்தை மற்றவருக்குக் கொடுக்கிறது. TTL-ஐ மட்டும் குறைக்காமல் cache directives, authorization கையாளுதல், cache key ஆகியவற்றை ஆராயுங்கள். தனிப்பட்ட content-க்கு சரியான சேமிப்புக் கொள்கை தேவை; Vary மட்டும் எல்லாச் சூழலுக்கும் தனியுரிமைப் பாதுகாப்பல்ல.'},
    lab:{commands:'curl --max-time 15 -sS -I https://example.com\ncurl --max-time 15 -sS -D - -o /dev/null https://example.com',guidance:{en:'Compare HEAD metadata with a GET whose body is discarded locally. Record status, cache directives, content type, and any validators. Public server headers can change, so do not assume this endpoint will demonstrate a 304 or that curl stores a browser-style cache.',ta:'HEAD metadata-ஐ, body உள்ளூரில் கைவிடப்படும் GET உடன் ஒப்பிடுங்கள். Status, cache directives, content type, validators இருந்தால் அவற்றையும் பதிவு செய்யுங்கள். பொது server headers மாறலாம்; இந்த endpoint கட்டாயம் 304 தரும் என்றோ curl browser போல cache வைத்திருக்கும் என்றோ கருதாதீர்கள்.'},expected:{en:'Headers show the server’s actual response and policy. Two successful curl requests may both transfer a representation because curl has not automatically reused a persistent HTTP cache.',ta:'Server-இன் உண்மையான response மற்றும் policy headers-இல் தெரியும். Curl நிரந்தர HTTP cache-ஐத் தானாக மீண்டும் பயன்படுத்தாததால் இரண்டு வெற்றியான requests-லும் representation அனுப்பப்படலாம்.'},cleanup:{en:'No files or configuration were changed.',ta:'கோப்புகளோ அமைப்புகளோ மாற்றப்படவில்லை.'}},
    questions:[
      {question:{en:'What does Cache-Control: no-cache permit?',ta:'Cache-Control: no-cache எதை அனுமதிக்கிறது?'},options:{en:['Storage with validation before reuse','Unconditional reuse forever','No HTTP responses'],ta:['சேமிக்கலாம்; மீள்பயன்பாட்டுக்கு முன் validation தேவை','எப்போதும் சரிபார்க்காமல் பயன்படுத்தலாம்','HTTP response-களே கிடையாது']},answer:0,explanation:{en:'No-cache and no-store impose different requirements.',ta:'No-cache மற்றும் no-store விதிக்கும் தேவைகள் வேறுபட்டவை.'}},
      {question:{en:'Age is 90 seconds and max-age is 60. What normally follows before ordinary reuse?',ta:'Age 90 வினாடிகள்; max-age 60. வழக்கமாக மீண்டும் பயன்படுத்துமுன் என்ன தேவை?'},options:{en:['Validation or a new response unless another rule permits stale reuse','A guaranteed cache hit without validation','DNS deletion'],ta:['Stale பயன்பாட்டை வேறு விதி அனுமதிக்காவிட்டால் validation அல்லது புதிய response','Validation இல்லாத உறுதியான cache hit','DNS அழித்தல்']},answer:0,explanation:{en:'The freshness lifetime has been exceeded by 30 seconds.',ta:'Freshness வாழ்நேரத்தை 30 வினாடிகள் கடந்துவிட்டது.'}},
      {question:{en:'Why does a 304 usually lack the requested representation body?',ta:'304 response-இல் கேட்ட representation body பொதுவாக ஏன் இல்லை?'},options:{en:['The cache already has the selected representation','TCP lost the whole body','The resource must be empty'],ta:['Cache-இல் தேர்ந்தெடுத்த representation ஏற்கெனவே உள்ளது','TCP முழு body-ஐ இழந்தது','Resource காலியாகவே இருக்க வேண்டும்']},answer:0,explanation:{en:'Validation avoids transferring an unchanged representation again.',ta:'மாறாத representation-ஐ மீண்டும் அனுப்புவதை validation தவிர்க்கிறது.'}}
    ],refs:[['HTTP semantics — RFC 9110','https://www.rfc-editor.org/rfc/rfc9110.html'],['HTTP caching — RFC 9111','https://www.rfc-editor.org/rfc/rfc9111.html']]
  },
  {
    id:18,module:4,model:'tls',title:{en:'TLS 1.3, certificates & HTTPS',ta:'TLS 1.3, certificates மற்றும் HTTPS'},
    summary:{en:'Explain authenticated key establishment and the limits of encrypted web transport.',ta:'அடையாளம் சரிபார்க்கப்பட்ட key உருவாக்கத்தையும் encrypt செய்யப்பட்ட web தொடர்பின் வரம்புகளையும் விளக்குங்கள்.'},
    prerequisites:{en:'Know TCP connections, HTTP requests, DNS names, and the distinction between public and secret key material.',ta:'TCP connection, HTTP request, DNS பெயர், public மற்றும் secret key தகவலின் வேறுபாடு ஆகியவை தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Connect handshake messages to authentication and traffic keys.','Check identity and certificate validity separately.','Explain replay risk and remaining metadata exposure.'],ta:['Handshake செய்திகளை authentication மற்றும் traffic keys உடன் இணைத்தல்.','பெயர் அடையாளத்தையும் certificate செல்லுபடியையும் தனித்தனியாகச் சரிபார்த்தல்.','Replay ஆபத்தையும் வெளியே தெரியக்கூடிய metadata-வையும் விளக்குதல்.']},
    sections:[
      {heading:{en:'From negotiation to protected records',ta:'Negotiation முதல் பாதுகாக்கப்பட்ட records வரை'},body:{en:'In a common certificate-based TLS 1.3 handshake, ClientHello offers supported parameters and key shares. ServerHello selects compatible parameters and contributes a key share. Ephemeral key agreement and a key schedule derive secrets used to protect later handshake and application records. The certificate and CertificateVerify connect the peer’s identity to possession of a private key; Finished authenticates the handshake transcript. Negotiation is not an agreement to trust every certificate, and application data must not be accepted merely because bytes are encrypted.',ta:'Certificate அடிப்படையிலான வழக்கமான TLS 1.3 handshake-இல் ClientHello ஆதரிக்கும் parameters மற்றும் key shares-ஐ வழங்குகிறது. ServerHello பொருந்தும் parameters-ஐத் தேர்ந்து தனது key share-ஐத் தருகிறது. Ephemeral key agreement மற்றும் key schedule மூலம் பிற handshake மற்றும் application records-க்கான secrets பெறப்படுகின்றன. Certificate மற்றும் CertificateVerify peer அடையாளத்தையும் private key வைத்திருப்பதையும் இணைக்கின்றன; Finished handshake transcript-ஐ உறுதிப்படுத்துகிறது. Parameters ஒத்துப்போனது எல்லா certificate-களையும் நம்புவதாகாது; bytes encrypt ஆகியுள்ளன என்பதற்காக மட்டும் application தரவை ஏற்கக் கூடாது.'}},
      {heading:{en:'Certificate verification and HTTPS',ta:'Certificate சரிபார்ப்பும் HTTPS-மும்'},body:{en:'A client checks an acceptable certification path to a configured trust anchor, certificate validity, and the intended service identity. For HTTPS, the requested hostname must match an appropriate certificate identity under the relevant rules. SNI can help a server select a virtual host, but sending SNI is not hostname verification. A trusted issuer does not certify that a business is honest. Revocation handling and trust stores depend on the client implementation, so document the actual verifier used in an experiment.',ta:'அமைக்கப்பட்ட trust anchor வரை ஏற்கத்தக்க certification path உள்ளதா, certificate காலவரம்பு சரியா, நோக்கமுள்ள service அடையாளம் சரியா என்று client சோதிக்கிறது. HTTPS-இல் கேட்ட hostname பொருத்தமான certificate அடையாளத்துடன் விதிப்படி பொருந்த வேண்டும். SNI மூலம் server virtual host-ஐத் தேர்ந்தெடுக்கலாம்; SNI அனுப்புவது hostname verification அல்ல. நம்பப்படும் issuer ஒரு வணிகம் நேர்மையானது என்று உறுதி அளிப்பதில்லை. Revocation கையாளுதலும் trust store-களும் client implementation-ஐச் சாரும்; ஆய்வில் பயன்படுத்திய verifier-ஐ ஆவணப்படுத்த வேண்டும்.'}},
      {heading:{en:'Protection boundaries and early data',ta:'பாதுகாப்பின் எல்லைகளும் early data-வும்'},body:{en:'TLS protects record confidentiality and integrity between its endpoints. A terminating proxy becomes one of those endpoints, while compromised applications can still expose plaintext. Observers can often infer addresses, timing, and traffic sizes. Resumption can reduce setup work; optional 0-RTT early data has replay risks and must be restricted to operations designed to tolerate them. Ephemeral key exchange can provide forward secrecy for ordinary session traffic, but that does not extend identical guarantees to replayable early data.',ta:'TLS தனது endpoints இடையே record ரகசியத்தன்மையையும் மாற்றமின்மையையும் பாதுகாக்கிறது. TLS-ஐ முடிக்கும் proxy ஒரு endpoint ஆகிறது; பாதிக்கப்பட்ட application plaintext-ஐ வெளியிடலாம். Address, நேரம், traffic அளவு போன்றவற்றை வெளியிலிருந்து கணிக்க முடியும். Resumption தொடக்கப் பணியைக் குறைக்கலாம்; விருப்பமான 0-RTT early data-க்கு replay ஆபத்து இருப்பதால் அதைத் தாங்கக்கூடிய செயல்களுக்கு மட்டுமே பயன்படுத்த வேண்டும். Ephemeral key exchange வழக்கமான session traffic-க்கு forward secrecy தரலாம்; replay செய்யக்கூடிய early data-க்கும் அதே உறுதிகள் உள்ளன என்று பொருளல்ல.'}}
    ],
    example:{en:'A browser requests https://shop.example but receives a validly signed certificate only for mail.example. The chain can be trusted while the service identity check fails. The correct repair is deploying a certificate covering shop.example on the intended virtual host, not disabling hostname checks.',ta:'Browser https://shop.example கேட்கிறது; mail.example-க்கு மட்டுமே உரிய சரியாகக் கையொப்பமிட்ட certificate வருகிறது. Chain நம்பத்தக்கதாக இருந்தாலும் service identity சோதனை தோல்வியடையும். சரியான virtual host-இல் shop.example-ஐ உள்ளடக்கும் certificate அமைப்பதே தீர்வு; hostname சோதனையை நிறுத்துவது அல்ல.'},
    failure:{en:'After a clock reset, HTTPS fails across many sites. Compare system time with certificate validity intervals before replacing certificates. If only one site fails, inspect its hostname, intermediate chain, and selected virtual host. Avoid treating curl -k as a repair; it removes important verification.',ta:'Clock மீட்டமைந்தபின் பல தளங்களில் HTTPS தோல்வியடைகிறது. Certificate-களை மாற்றுமுன் system நேரத்தை அவற்றின் காலவரம்புடன் ஒப்பிடுங்கள். ஒரு தளம் மட்டும் பாதிக்கப்பட்டால் hostname, intermediate chain, virtual host ஆகியவற்றைப் பாருங்கள். Curl -k முக்கிய verification-ஐ நீக்குவதால் அதைத் தீர்வாகக் கருதாதீர்கள்.'},
    lab:{commands:'date -u\ncurl --max-time 15 -vI https://example.com\ntimeout 20 openssl s_client -connect example.com:443 -servername example.com -verify_hostname example.com -verify_return_error -brief < /dev/null',guidance:{en:'Use curl, OpenSSL, and GNU timeout. Inspect negotiated TLS version and verification output. The explicit hostname check matters: s_client is a diagnostic tool, and merely displaying a certificate would not establish successful identity verification.',ta:'Curl, OpenSSL, GNU timeout தேவை. தேர்ந்தெடுத்த TLS version மற்றும் verification வெளியீட்டைப் பாருங்கள். வெளிப்படையான hostname சோதனை முக்கியம்: s_client ஓர் ஆய்வுக் கருவி; certificate-ஐக் காட்டுவது மட்டும் அடையாளச் சோதனை வெற்றியை நிறுவாது.'},expected:{en:'With working connectivity and a suitable trust store, verification succeeds. A timeout, missing CA store, or policy restriction is an observed environmental limitation, not proof that TLS itself is broken.',ta:'தொடர்பும் பொருத்தமான trust store-மும் இருந்தால் verification வெற்றி பெறும். Timeout, CA store இல்லாமை, policy தடை ஆகியவை சூழல் வரம்புகள்; TLS முறையே பழுதானது என்பதற்கான ஆதாரம் அல்ல.'},cleanup:{en:'No persistent state was created.',ta:'நிரந்தர மாற்றம் உருவாக்கப்படவில்லை.'}},
    questions:[
      {question:{en:'What does CertificateVerify demonstrate?',ta:'CertificateVerify எதை நிரூபிக்க உதவுகிறது?'},options:{en:['Possession of the certificate private key bound to the handshake','That the website has no bugs','That DNS is encrypted'],ta:['Handshake உடன் இணைந்த certificate private key வைத்திருப்பதை','Website-இல் பிழைகளே இல்லை என்பதை','DNS encrypt செய்யப்பட்டது என்பதை']},answer:0,explanation:{en:'Its signature authenticates relevant handshake context using the certificate key.',ta:'Certificate key கொண்டு தொடர்புடைய handshake சூழலுக்கு signature வழங்கப்படுகிறது.'}},
      {question:{en:'A trusted certificate covers api.example, but the URL is pay.example. What should the client do?',ta:'நம்பப்படும் certificate api.example-க்கு உரியது; URL pay.example. Client என்ன செய்ய வேண்டும்?'},options:{en:['Reject the identity mismatch','Accept because the issuer is trusted','Ignore the URL'],ta:['அடையாளப் பொருத்தமின்மையை நிராகரிக்க வேண்டும்','Issuer நம்பத்தக்கதால் ஏற்க வேண்டும்','URL-ஐப் புறக்கணிக்க வேண்டும்']},answer:0,explanation:{en:'A valid chain does not replace matching the intended service identity.',ta:'சரியான chain இருந்தாலும் நோக்கமுள்ள service அடையாளம் பொருந்த வேண்டிய தேவை நீங்காது.'}},
      {question:{en:'Why is a money transfer unsuitable for unrestricted 0-RTT processing?',ta:'பணப் பரிமாற்றத்தை வரம்பின்றி 0-RTT-இல் செயலாக்குவது ஏன் பொருத்தமற்றது?'},options:{en:['Replayed early data could repeat a sensitive operation','TLS cannot carry numbers','Certificates prohibit POST'],ta:['Early data replay முக்கியச் செயலை மீண்டும் செய்யவைக்கலாம்','TLS எண்களை எடுத்துச் செல்லாது','Certificate POST-ஐத் தடுக்கிறது']},answer:0,explanation:{en:'Application replay defenses and early-data policy must account for duplicate operations.',ta:'நகல் செயல்கள் நிகழ்வதை application replay பாதுகாப்பும் early-data policy-யும் கணக்கில் கொள்ள வேண்டும்.'}}
    ],refs:[['TLS 1.3 — RFC 8446','https://www.rfc-editor.org/rfc/rfc8446.html'],['Service identity — RFC 9525','https://www.rfc-editor.org/rfc/rfc9525.html']]
  },
  {
    id:19,module:4,model:'quic',title:{en:'HTTP/2, QUIC & HTTP/3',ta:'HTTP/2, QUIC மற்றும் HTTP/3'},
    summary:{en:'Compare stream multiplexing, loss recovery, and protocol negotiation without assuming newer is always faster.',ta:'புதியது எப்போதும் வேகமானது என்று கருதாமல் stream multiplexing, loss recovery, protocol negotiation ஆகியவற்றை ஒப்பிடுங்கள்.'},
    prerequisites:{en:'Understand ordered TCP delivery, packet loss, HTTP semantics, and TLS authentication.',ta:'TCP வரிசைப்படுத்திய வழங்கல், packet இழப்பு, HTTP பொருள், TLS authentication ஆகியவற்றைப் புரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Locate transport head-of-line blocking.','Explain QUIC stream independence and shared limits.','Verify negotiated versions before comparing performance.'],ta:['Transport head-of-line blocking எங்கே ஏற்படுகிறது என்பதைக் கண்டறிதல்.','QUIC stream தனித்தன்மையையும் பகிரப்பட்ட வரம்புகளையும் விளக்குதல்.','செயல்திறனை ஒப்பிடுமுன் தேர்ந்தெடுக்கப்பட்ட version-ஐச் சரிபார்த்தல்.']},
    sections:[
      {heading:{en:'Multiplexing over TCP',ta:'TCP மீது multiplexing'},body:{en:'HTTP/2 carries concurrent exchanges as frames on streams within one connection. This avoids requiring a separate TCP connection for every simultaneous request and replaces HTTP/1.1 message serialization with explicit framing. However, TCP still delivers one ordered byte stream. A missing TCP segment can delay delivery of later bytes containing frames for otherwise unrelated HTTP/2 streams. Application scheduling and stream flow control add further dependencies; multiplexing does not imply unlimited concurrency or eliminate server processing delays.',ta:'HTTP/2 ஒரே connection-இல் streams மற்றும் frames மூலம் ஒரேநேரப் பரிமாற்றங்களை எடுத்துச் செல்கிறது. ஒவ்வொரு simultaneous request-க்கும் தனி TCP connection தேவைப்படுவதை இது குறைக்கிறது; HTTP/1.1 செய்தி வரிசைக்குப் பதில் வெளிப்படையான framing வழங்குகிறது. ஆனால் TCP இன்னும் ஒரே வரிசைப்படுத்திய byte stream-ஐத் தருகிறது. ஒரு TCP segment தவறினால் தொடர்பற்ற HTTP/2 stream frames உள்ள பிற bytes வழங்கப்படுவதும் தாமதமாகலாம். Application scheduling, stream flow control ஆகியவையும் சார்புகளை உருவாக்கும்; multiplexing எல்லையற்ற concurrency-யையோ server தாமதமின்மையையோ குறிக்காது.'}},
      {heading:{en:'QUIC transport and HTTP/3 mapping',ta:'QUIC transport மற்றும் HTTP/3 mapping'},body:{en:'QUIC runs over UDP but supplies its own secure connection establishment, reliable streams, loss recovery, and congestion control. HTTP/3 maps HTTP exchanges onto QUIC streams. Loss on one stream need not block delivery of already received data on another stream. Streams still share connection congestion control and connection-level flow-control limits, and compression dependencies can also delay processing. UDP underneath therefore does not mean HTTP/3 is unreliable or that it ignores congestion; the transport responsibilities moved into QUIC.',ta:'QUIC, UDP மீது இயங்கினாலும் பாதுகாப்பான connection தொடக்கம், reliable streams, loss recovery, congestion control ஆகியவற்றைத் தானே வழங்குகிறது. HTTP/3 HTTP பரிமாற்றங்களை QUIC streams-க்கு இணைக்கிறது. ஒரு stream-இன் இழப்பு மற்றொன்றில் ஏற்கெனவே வந்த தரவை வழங்குவதை அவசியம் தடுக்காது. இருந்தாலும் streams ஒரே connection congestion control மற்றும் connection-level flow-control வரம்புகளைப் பகிர்கின்றன; compression சார்புகளும் செயலாக்கத்தைத் தாமதிக்கலாம். அடியில் UDP இருப்பதால் HTTP/3 நம்பகமற்றது என்றோ congestion-ஐப் புறக்கணிக்கிறது என்றோ பொருளல்ல; transport பொறுப்புகள் QUIC-க்குள் சென்றுள்ளன.'}},
      {heading:{en:'Negotiation, migration, and comparison',ta:'Negotiation, migration மற்றும் ஒப்பீடு'},body:{en:'Clients discover HTTP/3 support through mechanisms such as Alt-Svc or suitable DNS service records and negotiate an application protocol. Availability depends on client builds, server support, and the path allowing UDP. QUIC connection IDs can support continuity across address changes, subject to validation and implementation policy; migration is not a promise that every movement succeeds. Compare versions using the same content, cache state, path conditions, and connection reuse policy. Report failures and fallback rather than counting fallback HTTP/2 traffic as HTTP/3.',ta:'Alt-Svc அல்லது பொருத்தமான DNS service records போன்ற வழிகளில் client HTTP/3 ஆதரவை அறிந்து application protocol-ஐத் தேர்ந்தெடுக்கிறது. Client build, server ஆதரவு, பாதையில் UDP அனுமதி ஆகியவை கிடைப்பை நிர்ணயிக்கின்றன. QUIC connection ID address மாறினாலும் தொடர்பைத் தொடர உதவலாம்; validation மற்றும் implementation policy பொருந்தும். ஒவ்வொரு இடமாற்றமும் வெற்றி என்ற உறுதி இல்லை. ஒரே content, cache நிலை, பாதைச் சூழல், connection reuse கொள்கையுடன் versions-ஐ ஒப்பிடுங்கள். Fallback HTTP/2 traffic-ஐ HTTP/3 என எண்ணாமல் தோல்வியையும் fallback-ஐயும் பதிவு செய்யுங்கள்.'}}
    ],
    example:{en:'Streams A and B share a connection. One packet carrying A data is lost; a later packet carrying B data arrives. TCP-based HTTP/2 may withhold those later bytes until the gap closes. QUIC can deliver B’s received stream data while recovering A, provided other flow-control and application dependencies allow it.',ta:'A, B streams ஒரே connection-ஐப் பகிர்கின்றன. A தரவுள்ள packet இழக்கிறது; பிறகு B தரவுள்ள packet வந்து சேர்கிறது. TCP அடிப்படையிலான HTTP/2 இடைவெளி நிரம்பும்வரை பின்னைய bytes-ஐத் தடுக்கலாம். மற்ற flow-control மற்றும் application சார்புகள் அனுமதித்தால் QUIC, A-ஐ மீட்கும்போதே B தரவை வழங்கலாம்.'},
    failure:{en:'A client supports HTTP/3 but only TCP-based requests work on a particular network. Check UDP reachability and explicit protocol negotiation before blaming certificates. A normal browser may fall back successfully, masking the blocked QUIC path; an HTTP/3-only test should expose that limitation.',ta:'Client HTTP/3 ஆதரித்தாலும் ஒரு network-இல் TCP requests மட்டும் இயங்குகின்றன. Certificate-ஐக் குறைகூறுமுன் UDP தொடர்பையும் protocol negotiation-ஐயும் பாருங்கள். Browser வெற்றியாக fallback செய்வதால் QUIC தடை மறையலாம்; HTTP/3-only சோதனை அந்த வரம்பைக் காட்ட வேண்டும்.'},
    lab:{commands:'curl -V\ncurl --max-time 15 -sS -o /dev/null -w "%{http_version}\\n" https://example.com\nif curl --help all | grep -q -- --http3-only; then\n  curl --http3-only --max-time 15 -sS -o /dev/null -w "%{http_version}\\n" https://example.com\nfi',guidance:{en:'Inspect compiled features first. The conditional runs an HTTP/3-only attempt only when the option exists. This public endpoint is not promised to offer HTTP/3; record unsupported builds and failed negotiation as results rather than installing or changing the network.',ta:'முதலில் build features-ஐப் பாருங்கள். Option இருந்தால் மட்டுமே conditional HTTP/3-only முயற்சியைச் செய்கிறது. இந்தப் பொது endpoint HTTP/3 தரும் என்ற உறுதி இல்லை; ஆதரவற்ற build அல்லது negotiation தோல்வியை முடிவாகப் பதிவு செய்யுங்கள்; network-ஐ மாற்றத் தேவையில்லை.'},expected:{en:'The ordinary request prints its actual version. The strict attempt either prints 3 or reports a concrete limitation; neither outcome alone compares performance.',ta:'சாதாரண request உண்மையில் பயன்படுத்திய version-ஐ அச்சிடும். கடுமையான முயற்சி 3 அல்லது குறிப்பிட்ட வரம்பைக் காட்டும்; இவை மட்டும் செயல்திறன் ஒப்பீடு அல்ல.'},cleanup:{en:'No persistent changes were made.',ta:'நிரந்தர மாற்றங்கள் செய்யப்படவில்லை.'}},
    questions:[
      {question:{en:'What provides reliable stream delivery for HTTP/3?',ta:'HTTP/3-க்கு reliable stream வழங்கலை எது தருகிறது?'},options:{en:['QUIC','UDP alone','Ethernet broadcasts'],ta:['QUIC','UDP மட்டும்','Ethernet broadcasts']},answer:0,explanation:{en:'QUIC implements reliability above UDP.',ta:'UDP-க்கு மேலாக QUIC reliability-ஐ செயல்படுத்துகிறது.'}},
      {question:{en:'Only stream A loses data. Why can stream B still slow down under QUIC?',ta:'A stream-இல் மட்டும் இழப்பு. QUIC-இல் B ஏன் மெதுவாகலாம்?'},options:{en:['Both share congestion-control capacity','QUIC always orders all streams together','B must use TCP'],ta:['இரண்டும் congestion-control capacity-ஐப் பகிர்கின்றன','QUIC எல்லா streams-ஐயும் ஒரே வரிசையில் கட்டாயம் வழங்குகிறது','B TCP பயன்படுத்த வேண்டும்']},answer:0,explanation:{en:'Removing cross-stream delivery blocking does not remove shared network limits.',ta:'Streams இடையிலான வழங்கல் தடையை நீக்குவது பகிரப்பட்ட network வரம்புகளை நீக்காது.'}},
      {question:{en:'A benchmark requests HTTP/3 but records version 2. What should be reported?',ta:'Benchmark HTTP/3 கேட்டாலும் version 2 பதிவாகிறது. எதை அறிக்கையிட வேண்டும்?'},options:{en:['Fallback; this run did not measure HTTP/3','A successful HTTP/3 result','A DNS cache hit'],ta:['Fallback; இந்த run HTTP/3-ஐ அளவிடவில்லை','வெற்றியான HTTP/3 முடிவு','DNS cache hit']},answer:0,explanation:{en:'Requested capability and negotiated protocol are different evidence.',ta:'கேட்ட திறனும் உண்மையில் தேர்ந்தெடுத்த protocol-மும் வேறு ஆதாரங்கள்.'}}
    ],refs:[['HTTP/2 — RFC 9113','https://www.rfc-editor.org/rfc/rfc9113.html'],['QUIC — RFC 9000','https://www.rfc-editor.org/rfc/rfc9000.html'],['HTTP/3 — RFC 9114','https://www.rfc-editor.org/rfc/rfc9114.html'],['curl options','https://curl.se/docs/manpage.html']]
  },
  {
    id:20,module:4,model:'services',title:{en:'SSH, email, time & service protocols',ta:'SSH, email, நேரம் மற்றும் service protocols'},
    summary:{en:'Separate service discovery, endpoint authentication, mail handling, and clock synchronization.',ta:'Service கண்டுபிடித்தல், endpoint அடையாளச் சோதனை, mail கையாளுதல், clock ஒத்திசைவு ஆகியவற்றைத் தனித்தனியாகப் புரிந்துகொள்ளுங்கள்.'},
    prerequisites:{en:'Know DNS records, ports, client/server roles, and why encryption and authorization differ.',ta:'DNS records, ports, client/server பணிகள் மற்றும் encryption, authorization வேறுபாடு தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Describe SSH host-key verification.','Trace submission, transfer, and mailbox access separately.','Interpret time synchronization and service discovery evidence.'],ta:['SSH host-key சரிபார்ப்பை விவரித்தல்.','Mail submission, transfer, mailbox அணுகலைத் தனித்தனியாகப் பின்தொடர்தல்.','நேர ஒத்திசைவு மற்றும் service discovery ஆதாரங்களை விளக்குதல்.']},
    sections:[
      {heading:{en:'SSH and administrative identity',ta:'SSH மற்றும் நிர்வாக அடையாளம்'},body:{en:'SSH provides an encrypted transport, server authentication through host keys, and subsequent user authentication. A user key answers who may log in; a host key answers which server is being contacted. On first contact, verify the host-key fingerprint through an independent trusted channel before accepting it. A changed key may reflect a legitimate rebuild, a wrong destination, or interception. SSH can also carry file transfer and forwarding channels, so successful login does not describe every capability enabled by server policy.',ta:'SSH encrypt செய்யப்பட்ட transport, host key மூலம் server authentication, பின்னர் user authentication ஆகியவற்றை வழங்குகிறது. User key யார் உள்நுழையலாம் என்பதையும் host key எந்த server-ஐ அணுகுகிறோம் என்பதையும் குறிக்கின்றன. முதல் தொடர்பில் host-key fingerprint-ஐ தனியான நம்பகமான வழியில் சரிபார்த்தபின் ஏற்க வேண்டும். மாறிய key சரியான rebuild, தவறான destination அல்லது interception காரணமாக இருக்கலாம். SSH file transfer மற்றும் forwarding channels-யும் எடுத்துச் செல்லலாம்; login வெற்றி server policy அனுமதிக்கும் எல்லாத் திறன்களையும் விளக்காது.'}},
      {heading:{en:'Email is a pipeline of roles',ta:'பல பணிகள் இணையும் email பாதை'},body:{en:'Mail submission accepts a user’s outgoing message; SMTP relays move it between mail systems, often using MX records to locate recipients’ servers. IMAP provides access to stored mailboxes rather than replacing server-to-server transfer. A relay accepting a message does not prove final delivery or that a human read it. Transport TLS protects a particular hop, not automatically the message across every relay and mailbox. SPF, DKIM, and DMARC address different domain authentication and handling questions; they do not make malicious message content safe.',ta:'Mail submission பயனரின் வெளியேறும் செய்தியை ஏற்கிறது; SMTP relays அதை mail systems இடையே நகர்த்துகின்றன. பெறுநரின் server-ஐக் கண்டுபிடிக்க MX records பயன்படலாம். IMAP சேமித்த mailbox-ஐ அணுக உதவுகிறது; server-to-server transfer-க்கு மாற்றல்ல. Relay செய்தியை ஏற்றது இறுதியாக வழங்கப்பட்டது அல்லது மனிதர் வாசித்தார் என்பதல்ல. Transport TLS குறிப்பிட்ட hop-ஐப் பாதுகாக்கிறது; எல்லா relay, mailbox வழியாகவும் செய்தியைத் தானாகப் பாதுகாக்காது. SPF, DKIM, DMARC domain authentication மற்றும் கையாளுதலின் வேறு கேள்விகளுக்கானவை; தீங்கான content-ஐப் பாதுகாப்பானதாக்காது.'}},
      {heading:{en:'Time and discovery are dependencies',ta:'நேரமும் discovery-யும் சார்புகள்'},body:{en:'NTP estimates clock offset and network delay using timestamp exchanges; unequal forward and reverse delays can bias the estimate. Stratum describes distance from a reference in the synchronization hierarchy, not guaranteed accuracy. Reliable time supports certificate checks, log correlation, and incident reconstruction. Service discovery can combine DNS SRV records with application-specific naming conventions, while multicast DNS is local-link discovery rather than ordinary global DNS delegation. Finding a service address still requires checking reachability, identity, and application permissions.',ta:'Timestamp பரிமாற்றம் மூலம் NTP clock offset மற்றும் network delay-ஐ மதிப்பிடுகிறது; முன், பின் பாதைத் தாமதங்கள் சமமில்லாவிட்டால் மதிப்பீடு சாயலாம். Stratum ஒத்திசைவு படிநிலையில் reference-இலிருந்து உள்ள தூரத்தைக் குறிக்கிறது; துல்லியத்திற்கான உறுதி அல்ல. சரியான நேரம் certificate சோதனை, log ஒப்பீடு, incident மீளாய்வு ஆகியவற்றுக்கு உதவும். DNS SRV records மற்றும் application பெயரிடும் விதிகள் service discovery-க்கு உதவலாம். Multicast DNS local-link discovery; உலகளாவிய DNS delegation அல்ல. Service address கிடைத்தாலும் தொடர்பு, அடையாளம், application அனுமதி சோதிக்கப்பட வேண்டும்.'}}
    ],
    example:{en:'An employee submits mail successfully, but the recipient cannot see it. Follow the submission queue, relay delivery status, destination response, and mailbox filtering separately. An SMTP acceptance at the first server identifies only one completed stage; checking IMAP connectivity cannot prove that the upstream relay delivered the message.',ta:'பணியாளர் mail submit செய்கிறார்; பெறுநருக்குத் தெரியவில்லை. Submission queue, relay delivery status, destination response, mailbox filtering ஆகியவற்றைத் தனியாகப் பின்தொடருங்கள். முதல் server-இன் SMTP acceptance ஒரு கட்டம் முடிந்ததையே காட்டும்; IMAP தொடர்பைச் சோதிப்பது upstream relay வழங்கியதை நிரூபிக்காது.'},
    failure:{en:'Administrators delete known_hosts after a host-key warning and unknowingly trust the wrong server. Instead compare the destination address and an independently obtained fingerprint, then update only the verified entry. Clock errors can separately cause TLS failures and misleading log order even when SSH transport works.',ta:'Host-key எச்சரிக்கைக்குப் பின் known_hosts-ஐ அழிப்பதால் தவறான server நம்பப்படலாம். Destination address மற்றும் தனியாகப் பெற்ற fingerprint-ஐ ஒப்பிட்டு உறுதியான entry-ஐ மட்டும் மாற்ற வேண்டும். SSH இயங்கினாலும் clock பிழை TLS தோல்வியையும் தவறான log வரிசையையும் தனியாக உண்டாக்கலாம்.'},
    lab:{commands:'ssh -V\nssh -G localhost\ndig example.com MX\ntimedatectl status\nss -tuln',guidance:{en:'Run on Linux with OpenSSH, DNS utilities, and systemd tools where available. ssh -G prints evaluated configuration without logging in. Inspect listeners and clock state, but do not infer that a listed port is reachable through a firewall or that every system uses systemd time synchronization.',ta:'OpenSSH, DNS utilities, systemd கருவிகள் உள்ள Linux-இல் இயக்குங்கள். ssh -G login செய்யாமல் கணக்கிட்ட configuration-ஐ அச்சிடுகிறது. Listeners மற்றும் clock நிலையைப் பாருங்கள்; பட்டியலிலுள்ள port firewall வழியாக அணுகக்கூடியது என்றோ எல்லா systems-மும் systemd நேரச் சேவை பயன்படுத்தும் என்றோ கருதாதீர்கள்.'},expected:{en:'Configuration, MX answers, local listeners, and time-service status provide distinct evidence. A null MX, when returned, explicitly indicates the domain does not accept mail.',ta:'Configuration, MX விடை, local listeners, நேரச் சேவை நிலை ஆகியவை வெவ்வேறு ஆதாரங்கள். Null MX கிடைத்தால் அந்த domain mail ஏற்கவில்லை என்று வெளிப்படையாகக் குறிக்கும்.'},cleanup:{en:'No login was performed and no configuration was changed.',ta:'Login செய்யப்படவில்லை; configuration மாற்றப்படவில்லை.'}},
    questions:[
      {question:{en:'Which key identifies an SSH server?',ta:'SSH server-ஐ அடையாளம் காட்டும் key எது?'},options:{en:['Host key','Every user’s password','DNS TTL'],ta:['Host key','ஒவ்வொரு பயனரின் password','DNS TTL']},answer:0,explanation:{en:'Host authentication and user authentication serve different directions of trust.',ta:'Host authentication மற்றும் user authentication நம்பிக்கையின் வெவ்வேறு திசைகளுக்கானவை.'}},
      {question:{en:'SMTP submission succeeded but no destination delivery record exists. What should be checked next?',ta:'SMTP submission வெற்றி; destination delivery பதிவு இல்லை. அடுத்து எதைப் பார்க்க வேண்டும்?'},options:{en:['Relay queue and delivery responses','Only the recipient’s screen brightness','Ethernet MTU must be reduced immediately'],ta:['Relay queue மற்றும் delivery responses','பெறுநரின் திரை ஒளியை மட்டும்','உடனே Ethernet MTU குறைக்க வேண்டும்']},answer:0,explanation:{en:'Submission and final delivery are separate stages with separate evidence.',ta:'Submission, இறுதி delivery இரண்டும் தனிக் கட்டங்கள்; தனி ஆதாரங்கள் தேவை.'}},
      {question:{en:'Does lower NTP stratum always guarantee a better clock estimate?',ta:'குறைந்த NTP stratum எப்போதும் சிறந்த clock மதிப்பீட்டை உறுதி செய்யுமா?'},options:{en:['No; path asymmetry and source quality also matter','Yes; stratum is measured error','Yes; DNS authenticates time'],ta:['இல்லை; பாதைச் சமமின்மையும் source தரமும் முக்கியம்','ஆம்; stratum அளந்த பிழையே','ஆம்; DNS நேரத்தை உறுதிப்படுத்துகிறது']},answer:0,explanation:{en:'Hierarchy position is not a direct accuracy measurement.',ta:'படிநிலை இடம் நேரடித் துல்லிய அளவீடு அல்ல.'}}
    ],refs:[['SSH architecture — RFC 4251','https://www.rfc-editor.org/rfc/rfc4251.html'],['SMTP — RFC 5321','https://www.rfc-editor.org/rfc/rfc5321.html'],['NTPv4 — RFC 5905','https://www.rfc-editor.org/rfc/rfc5905.html'],['IMAP4rev2 — RFC 9051','https://www.rfc-editor.org/rfc/rfc9051.html']]
  },
  {
    id:21,module:5,model:'routing',title:{en:'Routing tables & longest-prefix match',ta:'Routing tables மற்றும் longest-prefix match'},
    summary:{en:'Predict route selection from destination prefixes, policy context, and next-hop reachability.',ta:'Destination prefix, policy சூழல், next-hop தொடர்பு ஆகியவற்றிலிருந்து route தேர்வைக் கணியுங்கள்.'},
    prerequisites:{en:'Calculate CIDR ranges and distinguish an IP destination from an Ethernet next-hop address.',ta:'CIDR வரம்பைக் கணக்கிடவும் IP destination மற்றும் Ethernet next-hop address-ஐ வேறுபடுத்தவும் தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Choose the most specific matching prefix.','Explain default routes and route metrics.','Separate route lookup from neighbor resolution and end-to-end delivery.'],ta:['பொருந்தும் மிகக் குறிப்பிட்ட prefix-ஐத் தேர்ந்தெடுத்தல்.','Default route மற்றும் route metrics-ஐ விளக்குதல்.','Route lookup, neighbor resolution, முழுப்பாதை வழங்கல் ஆகியவற்றை வேறுபடுத்துதல்.']},
    sections:[
      {heading:{en:'Destination lookup and specificity',ta:'Destination தேடலும் குறிப்புத்தன்மையும்'},body:{en:'A route describes reachability for a destination prefix and an action such as forwarding through an interface or gateway. Within the relevant routing lookup, the longest matching prefix wins: a /24 is more specific than a /16, which is more specific than /0. This is a comparison of matching address bits, not the visual length of an address string. A default route matches destinations lacking a more specific eligible route; it does not mean all traffic must use the default gateway.',ta:'ஒரு destination prefix-க்கு செல்லும் வழியையும் interface அல்லது gateway வழி அனுப்புதல் போன்ற செயலையும் route குறிப்பிடுகிறது. தொடர்புடைய routing lookup-இல் அதிக நீளமுள்ள பொருந்தும் prefix வெல்லும்: /24 என்பது /16-ஐவிடவும் அது /0-ஐவிடவும் குறிப்பானது. இது address bits பொருத்தத்தைப் பற்றியது; address எழுத்துச் சரத்தின் தோற்ற நீளம் அல்ல. மேலும் குறிப்பான தகுதியுள்ள route இல்லாத destination-க்கு default route பொருந்தும்; எல்லா traffic-மும் default gateway வழியாகவே செல்லும் என்பதல்ல.'}},
      {heading:{en:'Policy, metrics, and forwarding',ta:'Policy, metrics மற்றும் forwarding'},body:{en:'Linux can use routing policy rules to select among tables using fields such as source address or packet marks. Therefore, a destination-only sketch of one table may not explain every packet. Metrics and implementation preferences help choose among otherwise competing routes; a low metric on a default does not outrank a matching /24 within ordinary longest-prefix selection. Route learning and forwarding are separate activities: control protocols or administrators install routes, while the data plane applies the resulting forwarding decisions.',ta:'Source address அல்லது packet mark போன்றவற்றைப் பயன்படுத்தி Linux routing policy rules பல tables இடையே தேர்வு செய்யலாம். எனவே ஒரு table-இல் destination மட்டும் பார்த்த வரைபடம் எல்லா packet-ஐயும் விளக்காது. Metrics மற்றும் implementation முன்னுரிமைகள் போட்டியிடும் routes இடையே உதவும்; வழக்கமான longest-prefix தேர்வில் default route-இன் குறைந்த metric பொருந்தும் /24-ஐ முந்தாது. Route கற்றலும் forwarding-மும் வேறு செயல்கள். Control protocols அல்லது நிர்வாகிகள் routes அமைக்கின்றனர்; data plane அதன் முடிவுகளைப் பயன்படுத்துகிறது.'}},
      {heading:{en:'Next hops, return paths, and failure',ta:'Next hop, திரும்பும் பாதை மற்றும் தோல்வி'},body:{en:'After selecting a route, an Ethernet sender resolves the selected local next hop using ARP or IPv6 Neighbor Discovery. A route can exist even when its gateway is unreachable. Routers decrement TTL or Hop Limit to bound looping traffic; ordinary forwarding does not remember an entire path inside each packet. Replies perform their own route lookup and can follow a different path. A successful outbound lookup therefore proves neither reverse reachability nor firewall permission, and asymmetric paths can complicate stateful filtering.',ta:'Route தேர்ந்தெடுத்தபின் Ethernet அனுப்புநர் ARP அல்லது IPv6 Neighbor Discovery மூலம் local next hop-ஐத் தீர்மானிக்கிறார். Gateway அணுகமுடியாவிட்டாலும் route இருக்கலாம். Loop traffic முடிவில்லாமல் செல்லாமல் routers TTL அல்லது Hop Limit-ஐக் குறைக்கின்றன; சாதாரண forwarding ஒவ்வொரு packet-க்குள்ளும் முழுப் பாதையைச் சேமிப்பதில்லை. Replies தனி route lookup செய்து வேறு பாதையில் வரலாம். எனவே வெளியேறும் lookup வெற்றி திரும்பும் தொடர்பையோ firewall அனுமதியையோ நிரூபிக்காது; சமமற்ற பாதைகள் stateful filtering-ஐச் சிக்கலாக்கலாம்.'}}
    ],
    example:{en:'Suppose the selected table contains 10.0.0.0/8 via A, 10.20.0.0/16 via B, and 0.0.0.0/0 via C. Destination 10.20.7.9 matches all three and uses B. Destination 10.30.7.9 uses A. A lower metric on C does not change these prefix matches.',ta:'தேர்ந்தெடுத்த table-இல் 10.0.0.0/8 → A, 10.20.0.0/16 → B, 0.0.0.0/0 → C உள்ளன. 10.20.7.9 மூன்றுக்கும் பொருந்தினாலும் B வழி செல்லும். 10.30.7.9 A வழி செல்லும். C-இன் metric குறைவாக இருப்பது இந்த prefix முடிவுகளை மாற்றாது.'},
    failure:{en:'A VPN installs a more specific route and an internal service suddenly goes through the tunnel. Compare policy rules and route-get output before deleting the default route. If lookup is correct but packets stall, inspect gateway neighbor state and the return path rather than assuming a missing route.',ta:'VPN மேலும் குறிப்பான route அமைத்ததால் உள் service திடீரென tunnel வழி செல்கிறது. Default route-ஐ அழிக்குமுன் policy rules மற்றும் route-get வெளியீட்டை ஒப்பிடுங்கள். Lookup சரியாக இருந்தும் packet நின்றால் route இல்லை என்று கருதாமல் gateway neighbor நிலையையும் திரும்பும் பாதையையும் பாருங்கள்.'},
    lab:{commands:'ip rule show\nip -4 route show table main\nip -4 route get 192.0.2.25\nip -4 route get 198.51.100.25\nip neigh show',guidance:{en:'These Linux commands inspect policy and hypothetical destination lookups without transmitting test packets to documentation addresses. Record selected source, interface, gateway, and table where shown. Compare with the matching prefixes in your actual configuration rather than expecting a particular gateway.',ta:'இந்த Linux commands documentation addresses-க்கு packet அனுப்பாமல் policy மற்றும் destination lookup-ஐப் பார்க்கின்றன. காட்டப்படும் source, interface, gateway, table ஆகியவற்றைப் பதிவு செய்யுங்கள். குறிப்பிட்ட gateway வரும் என்று எதிர்பார்க்காமல் உங்கள் configuration-இன் பொருந்தும் prefixes உடன் ஒப்பிடுங்கள்.'},expected:{en:'An available route produces a selected path; an unreachable lookup can legitimately report an error. Neighbor entries provide a separate view of local next-hop resolution.',ta:'Route இருந்தால் தேர்ந்தெடுத்த பாதை தெரியும்; வழியில்லாத lookup பிழை தரலாம். Neighbor entries local next-hop தீர்மானத்தின் தனி நிலையைத் தருகின்றன.'},cleanup:{en:'No routes or policy rules were changed.',ta:'Routes அல்லது policy rules மாற்றப்படவில்லை.'}},
    questions:[
      {question:{en:'Which prefix wins for 10.2.3.4 among /0, 10.0.0.0/8, and 10.2.3.0/24?',ta:'10.2.3.4-க்கு /0, 10.0.0.0/8, 10.2.3.0/24 ஆகியவற்றில் எது வெல்லும்?'},options:{en:['10.2.3.0/24','0.0.0.0/0','10.0.0.0/8'],ta:['10.2.3.0/24','0.0.0.0/0','10.0.0.0/8']},answer:0,explanation:{en:'Twenty-four matching prefix bits give the most specific match.',ta:'24 prefix bits பொருந்துவதால் அதுவே மிகக் குறிப்பான route.'}},
      {question:{en:'A route exists but its next-hop ARP entry stays incomplete. Where is the immediate problem?',ta:'Route உள்ளது; next-hop ARP entry incomplete-ஆக உள்ளது. உடனடிச் சிக்கல் எங்கே?'},options:{en:['Local next-hop resolution or link reachability','HTTP caching must be broken','The route proves successful delivery'],ta:['Local next-hop தீர்மானம் அல்லது link தொடர்பு','HTTP caching கட்டாயம் பழுதாகியுள்ளது','Route இருப்பது delivery வெற்றியை நிரூபிக்கிறது']},answer:0,explanation:{en:'Forwarding needs a usable local-link next hop after route selection.',ta:'Route தேர்வுக்குப் பிறகு forwarding-க்கு பயன்படுத்தக்கூடிய local-link next hop தேவை.'}},
      {question:{en:'Why inspect ip rule as well as the main table?',ta:'Main table உடன் ip rule-ஐயும் ஏன் பார்க்க வேண்டும்?'},options:{en:['Policy may direct lookup to another table','Rules contain DNS cache records','The main table never routes packets'],ta:['Policy வேறொரு table-க்கு lookup-ஐ அனுப்பலாம்','Rules DNS cache records வைத்துள்ளன','Main table packet route செய்வதே இல்லை']},answer:0,explanation:{en:'Source and other policy selectors can change the lookup context.',ta:'Source மற்றும் பிற policy தேர்வுகள் lookup சூழலை மாற்றலாம்.'}}
    ],refs:[['IPv4 router requirements — RFC 1812','https://www.rfc-editor.org/rfc/rfc1812.html'],['ip-route manual','https://man7.org/linux/man-pages/man8/ip-route.8.html'],['ip-rule manual','https://man7.org/linux/man-pages/man8/ip-rule.8.html']]
  },
  {
    id:22,module:5,model:'nat',title:{en:'NAT, PAT & inbound connections',ta:'NAT, PAT மற்றும் உள்ளே வரும் connections'},
    summary:{en:'Track translated tuples, return mapping state, and the conditions needed for inbound reachability.',ta:'மாற்றப்பட்ட address-port தொகுதி, reply mapping நிலை, வெளியிலிருந்து அணுகத் தேவையான நிபந்தனைகளைப் பின்தொடருங்கள்.'},
    prerequisites:{en:'Understand private IPv4, TCP/UDP endpoints, routing, and stateful connection tracking.',ta:'Private IPv4, TCP/UDP endpoints, routing, stateful connection tracking ஆகியவற்றைப் புரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Follow source and destination translation.','Explain why PAT needs ports and protocol state.','Diagnose port-forwarding failures across multiple translators.'],ta:['Source மற்றும் destination translation-ஐப் பின்தொடர்தல்.','PAT-க்கு port மற்றும் protocol நிலை ஏன் தேவை என்று விளக்குதல்.','பல translators வழியாக port-forwarding தோல்வியைக் கண்டறிதல்.']},
    sections:[
      {heading:{en:'Address and port mappings',ta:'Address மற்றும் port mappings'},body:{en:'Basic NAT rewrites addresses between realms; NAPT, often called PAT, also translates transport identifiers so several internal hosts can share an external IPv4 address. A mapping associates internal and external tuples, including protocol where appropriate. The translator updates affected checksums, and return packets need the corresponding reverse operation. Source translation commonly changes an outbound source, while destination translation can direct inbound traffic to an internal server. Translation changes packet fields; routing still chooses how the resulting packet is forwarded.',ta:'Basic NAT address-களை network பகுதிகளுக்கு இடையே மாற்றுகிறது. PAT என்றும் அழைக்கப்படும் NAPT transport அடையாளங்களையும் மாற்றுவதால் பல உள் hosts ஒரே வெளி IPv4 address-ஐப் பகிரலாம். Mapping உள், வெளி address-port தொகுதிகளையும் பொருத்தமான protocol-ஐயும் இணைக்கிறது. Translator பாதிக்கப்படும் checksums-ஐப் புதுப்பிக்கும்; reply packet-க்கு எதிர்திசை மாற்றம் தேவை. Source translation வெளியேறும் source-ஐ மாற்றலாம்; destination translation உள்ளே வரும் traffic-ஐ உள் server-க்கு அனுப்பலாம். Translation fields-ஐ மாற்றுகிறது; மாற்றிய packet எங்கு செல்லும் என்பதை routing தீர்மானிக்கிறது.'}},
      {heading:{en:'State is not universal permission',ta:'State என்பது எல்லையற்ற அனுமதி அல்ல'},body:{en:'Dynamic mappings typically expire when inactive, with protocol-specific handling. A UDP mapping does not turn UDP into a reliable connection. Mapping and filtering behaviors are related but distinct: an external address-port association does not automatically authorize packets from every remote peer. A stateful firewall may permit expected replies while rejecting unsolicited traffic. NAT and firewall policy often coexist in a home router, but address translation itself is not a complete security policy and is not a requirement for IPv6 security.',ta:'செயலற்ற dynamic mappings பொதுவாக protocol-க்கேற்ற விதிப்படி காலாவதியாகின்றன. UDP mapping இருப்பதால் UDP reliable connection ஆகாது. Mapping மற்றும் filtering தொடர்புடையவையாக இருந்தாலும் வேறு செயல்கள். வெளி address-port ஒதுக்கீடு இருப்பது எல்லா remote peers-இலிருந்தும் packet அனுமதிக்கிறது என்பதல்ல. Stateful firewall எதிர்பார்த்த replies-ஐ அனுமதித்து எதிர்பாராத traffic-ஐத் தடுக்கலாம். வீட்டு router-இல் NAT மற்றும் firewall இணைந்திருக்கலாம்; address translation மட்டும் முழு security policy அல்ல; IPv6 பாதுகாப்புக்கும் NAT கட்டாயமல்ல.'}},
      {heading:{en:'Inbound service and layered NAT',ta:'உள்ளே வரும் சேவையும் பல NAT அடுக்குகளும்'},body:{en:'An inbound service generally needs a reachable external endpoint, a suitable destination mapping, a forwarding route, firewall permission, a listening application, and a valid return path. Port forwarding on one router cannot configure an upstream carrier-grade NAT. Shared address space 100.64.0.0/10 is designated for service-provider use and is different from RFC 1918 private space. Testing from inside through the external address may also require hairpin translation support. Check each boundary instead of assuming one forwarding rule makes the server public.',ta:'வெளியிலிருந்து service அணுக வெளியில் அடையக்கூடிய endpoint, பொருத்தமான destination mapping, forwarding route, firewall அனுமதி, கேட்கும் application, சரியான reply பாதை தேவை. ஒரு router-இல் port forwarding செய்வதால் upstream carrier-grade NAT அமைப்பு மாறாது. 100.64.0.0/10 shared address space சேவை வழங்குநருக்காக ஒதுக்கப்பட்டது; இது RFC 1918 private space-இலிருந்து வேறு. உள்ளே இருந்தபடி வெளி address வழியாகச் சோதிக்க hairpin translation ஆதரவும் தேவைப்படலாம். ஒரே forwarding rule server-ஐப் பொதுவாக்கும் என்று கருதாமல் ஒவ்வொரு எல்லையையும் சோதிக்க வேண்டும்.'}}
    ],
    example:{en:'Host 192.168.1.10:51000 connects to 198.51.100.20:443 using TCP. A translator maps its source to 203.0.113.5:62001. The reply to 203.0.113.5:62001 is translated back to 192.168.1.10:51000. These documentation addresses illustrate tuples, not live services. Another internal host needs a distinguishable mapping for the same remote flow.',ta:'192.168.1.10:51000 host, TCP மூலம் 198.51.100.20:443-ஐ அணுகுகிறது. Translator source-ஐ 203.0.113.5:62001 என மாற்றுகிறது. அந்த வெளி endpoint-க்கு வரும் reply மீண்டும் 192.168.1.10:51000 ஆக மாற்றப்படுகிறது. இவை விளக்கத்திற்கான documentation addresses; நேரடி சேவைகள் அல்ல. அதே remote flow-ஐ அணுகும் இன்னொரு உள் host-க்கு வேறுபடுத்தக்கூடிய mapping தேவை.'},
    failure:{en:'A forwarded home server is reachable on the LAN but not from a separate authorized network. The router WAN address is in 100.64.0.0/10. This suggests another translation boundary; inspect the provider arrangement, firewall, and listener before repeatedly editing the local forward.',ta:'Forward செய்த வீட்டு server LAN-இல் கிடைக்கிறது; அனுமதிக்கப்பட்ட வேறு network-இலிருந்து கிடைக்கவில்லை. Router WAN address 100.64.0.0/10-இல் உள்ளது. இது கூடுதல் translation எல்லையைச் சுட்டுகிறது; local forwarding-ஐ மீண்டும் மாற்றுமுன் provider அமைப்பு, firewall, listener ஆகியவற்றைப் பாருங்கள்.'},
    lab:{commands:'ip -4 addr show\nip -4 route show\nss -tuln\nif command -v nft >/dev/null; then sudo nft list ruleset; fi',guidance:{en:'Inspect only a Linux host or router you administer. Reading nftables requires privilege and may reveal policy details; keep the output local. A workstation may perform no NAT because translation occurs on another device. Do not add forwarding rules during this inspection exercise.',ta:'நீங்கள் நிர்வகிக்கும் Linux host அல்லது router-ஐ மட்டும் பாருங்கள். Nftables வாசிக்க privilege தேவை; policy தகவல் தெரியலாம் என்பதால் வெளியீட்டை உள்ளூரில் வைத்திருங்கள். Translation வேறு சாதனத்தில் நடந்தால் workstation NAT செய்யாமல் இருக்கலாம். இந்த ஆய்வில் forwarding rules சேர்க்க வேண்டாம்.'},expected:{en:'Identify addresses, listeners, and any visible NAT chains separately. An empty local NAT ruleset does not establish that the end-to-end path has no NAT.',ta:'Addresses, listeners, தெரியும் NAT chains ஆகியவற்றைத் தனியாக அடையாளப்படுத்துங்கள். Local NAT rules இல்லாதது முழுப் பாதையிலும் NAT இல்லை என்பதை நிறுவாது.'},cleanup:{en:'No mappings or rules were created.',ta:'Mappings அல்லது rules உருவாக்கப்படவில்லை.'}},
    questions:[
      {question:{en:'Why translate ports when sharing one public IPv4 address?',ta:'ஒரே public IPv4 address பகிரும்போது ports-ஐ ஏன் மாற்றுகிறோம்?'},options:{en:['To distinguish concurrent transport mappings','To encrypt the payload','To eliminate routing'],ta:['ஒரேநேர transport mappings-ஐ வேறுபடுத்த','Payload-ஐ encrypt செய்ய','Routing-ஐ நீக்க']},answer:0,explanation:{en:'Ports and protocol contribute to distinguishing transport endpoints.',ta:'Transport endpoints-ஐ வேறுபடுத்த ports மற்றும் protocol உதவுகின்றன.'}},
      {question:{en:'The external source becomes :62001. Where must the corresponding reply be sent?',ta:'வெளி source port :62001 ஆகிறது. அதற்கான reply எங்கு அனுப்பப்பட வேண்டும்?'},options:{en:['The mapped external address and port 62001','Directly to the private address over the public Internet','Any port on any router'],ta:['Mapped வெளி address மற்றும் port 62001','Public Internet வழியாக நேரடியாக private address-க்கு','எந்த router-இன் எந்த port-க்கும்']},answer:0,explanation:{en:'Reverse translation uses the mapping associated with that external tuple.',ta:'அந்த வெளித் தொகுதியுடன் இணைந்த mapping மூலம் எதிர்திசை மாற்றம் நடக்கிறது.'}},
      {question:{en:'Does a local port forward control the provider’s CGN?',ta:'Local port forward provider-இன் CGN-ஐக் கட்டுப்படுத்துமா?'},options:{en:['No; each translation boundary has its own policy','Yes; NAT rules propagate like BGP','Yes; UDP bypasses CGN'],ta:['இல்லை; ஒவ்வொரு translation எல்லைக்கும் தனி policy','ஆம்; NAT rules BGP போலப் பரவும்','ஆம்; UDP CGN-ஐத் தவிர்க்கும்']},answer:0,explanation:{en:'Upstream reachability must be provided independently.',ta:'Upstream அணுகல் தனியாக வழங்கப்பட வேண்டும்.'}}
    ],refs:[['Traditional NAT — RFC 3022','https://www.rfc-editor.org/rfc/rfc3022.html'],['UDP NAT behavior — RFC 4787','https://www.rfc-editor.org/rfc/rfc4787.html'],['Shared address space — RFC 6598','https://www.rfc-editor.org/rfc/rfc6598.html']]
  },
  {
    id:23,module:5,model:'bgp',title:{en:'OSPF, BGP & the global Internet',ta:'OSPF, BGP மற்றும் உலக Internet'},
    summary:{en:'Connect internal topology computation with interdomain policy and route-origin validation.',ta:'உள் topology கணக்கீட்டை networks இடையிலான policy மற்றும் route-origin validation உடன் இணைத்துப் புரிந்துகொள்ளுங்கள்.'},
    prerequisites:{en:'Understand prefixes, routing tables, next hops, and the separation between routing decisions and forwarding.',ta:'Prefixes, routing tables, next hops, routing முடிவு மற்றும் forwarding வேறுபாடு ஆகியவை தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Compare OSPF link-state operation with BGP path attributes.','Explain policy preference without geographic assumptions.','Interpret RPKI origin states within their limits.'],ta:['OSPF link-state செயல்பாட்டை BGP path attributes உடன் ஒப்பிடுதல்.','புவியியல் ஊகமின்றி policy முன்னுரிமையை விளக்குதல்.','RPKI origin நிலைகளை அவற்றின் வரம்புடன் புரிந்துகொள்ளுதல்.']},
    sections:[
      {heading:{en:'OSPF inside a routing domain',ta:'Routing domain-க்குள் OSPF'},body:{en:'OSPF is an interior link-state routing protocol. Routers establish eligible adjacencies, distribute link-state advertisements, and compute paths from a topology database. The shortest path is measured using configured link costs, not necessarily physical distance or observed application latency. Areas structure the topology and information exchange; routers do not all need an identical detailed view of every area. After a topology change, detection, flooding, computation, and forwarding updates take time, so convergence is a process rather than an instantaneous global switch.',ta:'OSPF ஓர் உள் link-state routing protocol. Routers தகுதியுள்ள adjacencies அமைத்து link-state advertisements பரப்பி topology database-இலிருந்து paths கணக்கிடுகின்றன. Shortest path என்பது அமைக்கப்பட்ட link costs அடிப்படையிலானது; உடல் தூரமோ application latency-யோ அவசியமல்ல. Areas topology மற்றும் தகவல் பரிமாற்றத்தை ஒழுங்குபடுத்துகின்றன; எல்லா routers-க்கும் எல்லா area-வின் முழு விவரமும் ஒரேபோல் தேவையில்லை. Topology மாறும்போது detection, flooding, computation, forwarding update ஆகியவற்றுக்கு நேரம் தேவை; convergence என்பது உடனடி உலகளாவிய மாற்றமல்ல.'}},
      {heading:{en:'BGP carries policy-rich reachability',ta:'Policy உடன் reachability பகிரும் BGP'},body:{en:'An autonomous system uses an ASN to participate in interdomain routing. BGP advertisements carry prefixes and attributes, including AS_PATH and NEXT_HOP. Import policy decides what to accept and prefer; export policy decides what to advertise onward. A higher local preference can outweigh a shorter AS path in common selection procedures. BGP also runs within an AS to distribute routes, while an IGP may provide reachability to internal next hops. A selected BGP route still needs a usable forwarding resolution.',ta:'Interdomain routing-இல் பங்கேற்க autonomous system ASN பயன்படுத்துகிறது. BGP advertisements prefixes மற்றும் AS_PATH, NEXT_HOP போன்ற attributes-ஐ எடுத்துச் செல்கின்றன. எதை ஏற்று விரும்புவது என்பதை import policy-யும் எதைப் பிறருக்குச் சொல்லுவது என்பதை export policy-யும் முடிவு செய்கின்றன. வழக்கமான தேர்வில் உயர்ந்த local preference குறுகிய AS path-ஐவிட முன்னுரிமை பெறலாம். AS-க்குள்ளும் BGP routes பகிரப்படுகிறது; உள் next hops-க்கான தொடர்பை IGP தரலாம். தேர்ந்தெடுத்த BGP route-க்கும் பயன்படுத்தக்கூடிய forwarding தீர்மானம் தேவை.'}},
      {heading:{en:'Filtering, leaks, and origin validation',ta:'Filtering, route leaks மற்றும் origin validation'},body:{en:'Operators filter unexpected prefixes and constrain customer announcements to reduce accidental or malicious propagation. RPKI route-origin validation compares an announcement’s prefix and origin ASN with validated authorizations. Valid, Invalid, and NotFound describe that check; NotFound is not proof of attack. A Valid origin does not authenticate the complete AS path or prove that export policy is appropriate. Route leaks can involve legitimate origins advertised across the wrong relationship, so operational defenses need policy controls in addition to origin validation.',ta:'தவறான அல்லது தீங்கான பரவலைக் குறைக்க operators எதிர்பாராத prefixes-ஐ வடிகட்டி customer announcements-ஐ வரம்பிடுகின்றனர். RPKI route-origin validation அறிவிப்பின் prefix, origin ASN ஆகியவற்றைச் சரிபார்க்கப்பட்ட authorizations உடன் ஒப்பிடுகிறது. Valid, Invalid, NotFound அந்தச் சோதனையின் நிலைகள்; NotFound தாக்குதலின் ஆதாரம் அல்ல. Valid origin முழு AS path-ஐ உறுதிப்படுத்தாது; export policy சரி என்பதையும் நிரூபிக்காது. சரியான origin கூட தவறான உறவு வழியாக அறிவிக்கப்பட்டால் route leak நிகழலாம்; origin validation உடன் policy கட்டுப்பாடுகளும் தேவை.'}}
    ],
    example:{en:'Two accepted routes reach the same prefix. Route A has local preference 200 and AS path length 4; route B has local preference 100 and AS path length 2. With the usual preference ordering and other eligibility checks satisfied, A wins. Counting AS hops alone predicts the wrong outcome, and neither count measures geographic distance.',ta:'ஒரே prefix-க்கு இரண்டு ஏற்ற routes உள்ளன. A-க்கு local preference 200, AS path நீளம் 4. B-க்கு preference 100, நீளம் 2. வழக்கமான முன்னுரிமை வரிசையிலும் மற்ற தகுதிகள் சரியாகவும் இருந்தால் A வெல்லும். AS hops மட்டும் எண்ணினால் தவறான முடிவு வரும்; அந்த எண்ணிக்கை புவியியல் தூரமும் அல்ல.'},
    failure:{en:'A learned BGP prefix appears in protocol output but never enters forwarding. Investigate next-hop reachability and competing routes before blaming packet filters. Separately, if many networks suddenly choose an unexpected transit path, inspect import/export changes and leaked advertisements rather than assuming OSPF chose a longer cable.',ta:'BGP கற்ற prefix protocol வெளியீட்டில் உள்ளது; forwarding-இல் இல்லை. Packet filters-ஐக் குறைகூறுமுன் next-hop தொடர்பையும் போட்டி routes-ஐயும் ஆராயுங்கள். பல networks திடீரென எதிர்பாராத transit பாதை தேர்ந்தால் OSPF நீளமான cable தேர்ந்தது என்று கருதாமல் import/export மாற்றங்களையும் leaked advertisements-ஐயும் பாருங்கள்.'},
    lab:{commands:'ip -4 route show\nip rule show\npython3 - <<\'PY\'\nroutes = [(200, 4, "A"), (100, 2, "B")]\nchosen = sorted(routes, key=lambda r: (-r[0], r[1]))[0]\nprint(chosen[2])\nPY',guidance:{en:'The Python exercise models only two preference criteria among already eligible routes; it is not a complete BGP implementation. Compare its result with your host’s ordinary routes. Do not open public routing sessions or announce prefixes for this lab.',ta:'Python பயிற்சி ஏற்கெனவே தகுதியுள்ள routes-இல் இரண்டு முன்னுரிமைகளை மட்டும் மாதிரியாக்குகிறது; முழு BGP implementation அல்ல. அதன் முடிவை host-இன் சாதாரண routes உடன் ஒப்பிடுங்கள். இந்த lab-க்காக public routing sessions திறக்கவோ prefixes அறிவிக்கவோ வேண்டாம்.'},expected:{en:'The model prints A. A laptop normally shows connected and default routes rather than a complete Internet BGP table.',ta:'மாதிரி A என்று அச்சிடும். Laptop பொதுவாக connected மற்றும் default routes-ஐத் தரும்; முழு Internet BGP table அல்ல.'},cleanup:{en:'The model runs in memory and changes no routes.',ta:'மாதிரி memory-இல் இயங்குகிறது; routes எதையும் மாற்றாது.'}},
    questions:[
      {question:{en:'What does OSPF shortest path minimize?',ta:'OSPF shortest path எதைக் குறைக்கிறது?'},options:{en:['Accumulated configured cost','Always geographic distance','Always HTTP response time'],ta:['சேர்க்கப்பட்ட configured cost','எப்போதும் புவியியல் தூரம்','எப்போதும் HTTP response நேரம்']},answer:0,explanation:{en:'The topology computation uses routing costs.',ta:'Topology கணக்கீடு routing costs-ஐப் பயன்படுத்துகிறது.'}},
      {question:{en:'Local preference 150/path 5 versus preference 100/path 2: which normally wins?',ta:'Local preference 150/path 5, preference 100/path 2: வழக்கமாக எது வெல்லும்?'},options:{en:['Preference 150, assuming both routes are eligible','Always path 2','Whichever prefix was typed first'],ta:['இரண்டும் தகுதியானால் preference 150','எப்போதும் path 2','முதலில் தட்டச்சான prefix']},answer:0,explanation:{en:'Local preference is considered before AS path length in the usual decision process.',ta:'வழக்கமான தேர்வில் AS path நீளத்திற்கு முன் local preference பார்க்கப்படுகிறது.'}},
      {question:{en:'What does a Valid RPKI origin result establish?',ta:'Valid RPKI origin முடிவு எதை நிறுவுகிறது?'},options:{en:['Prefix and origin satisfy a validated authorization','Every transit AS is trustworthy','The route cannot be leaked'],ta:['Prefix மற்றும் origin சரிபார்த்த authorization-க்கு பொருந்துகின்றன','ஒவ்வொரு transit AS-மும் நம்பத்தக்கது','அந்த route leak ஆகவே முடியாது']},answer:0,explanation:{en:'Origin validation has a narrower scope than full path or export-policy validation.',ta:'Origin validation முழுப் பாதை அல்லது export-policy validation-ஐவிடக் குறுகிய வரம்புடையது.'}}
    ],refs:[['OSPFv2 — RFC 2328','https://www.rfc-editor.org/rfc/rfc2328.html'],['BGP-4 — RFC 4271','https://www.rfc-editor.org/rfc/rfc4271.html'],['Origin validation — RFC 6811','https://www.rfc-editor.org/rfc/rfc6811.html']]
  },
  {
    id:24,module:5,model:'qos',title:{en:'Multicast, QoS & load balancing',ta:'Multicast, QoS மற்றும் load balancing'},
    summary:{en:'Distinguish group delivery, bottleneck scheduling, and backend selection as separate infrastructure functions.',ta:'குழுவுக்கான வழங்கல், bottleneck scheduling, backend தேர்வு ஆகியவற்றைத் தனித்தனி infrastructure பணிகளாகப் புரிந்துகொள்ளுங்கள்.'},
    prerequisites:{en:'Understand unicast, finite queues, link capacity, and client/server requests.',ta:'Unicast, வரம்புள்ள queues, link capacity, client/server requests ஆகியவை தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Explain multicast membership and replication.','Compare shaping, policing, and queue scheduling.','Evaluate load-balancer health and session behavior.'],ta:['Multicast உறுப்பினர் நிலை மற்றும் replication-ஐ விளக்குதல்.','Shaping, policing, queue scheduling-ஐ ஒப்பிடுதல்.','Load-balancer health மற்றும் session செயல்பாட்டை மதிப்பிடுதல்.']},
    sections:[
      {heading:{en:'Multicast delivers to interested groups',ta:'விரும்பும் குழுவுக்கு வழங்கும் multicast'},body:{en:'Multicast sends to a group address and can replicate packets at branching points instead of sending a separate source copy to every receiver. IPv4 hosts signal membership with IGMP; IPv6 uses MLD. Membership signaling on a local link is distinct from multicast routing between networks. Switch snooping can limit unnecessary flooding when correctly deployed, but multicast is not automatically available across the public Internet. Group membership is not user authentication, and ordinary IP multicast does not itself guarantee reliable or confidential delivery.',ta:'Multicast ஒரு group address-க்கு அனுப்பி கிளையும் இடங்களில் packet நகல்களை உருவாக்கலாம்; ஒவ்வொரு receiver-க்கும் source தனி நகல் அனுப்பத் தேவையில்லை. IPv4 hosts IGMP மூலமும் IPv6 MLD மூலமும் membership தெரிவிக்கின்றன. Local link membership signaling மற்றும் networks இடையிலான multicast routing வேறு. சரியாக அமைத்த switch snooping தேவையற்ற flooding-ஐக் குறைக்கலாம்; public Internet முழுவதும் multicast தானாகக் கிடைப்பதில்லை. Group உறுப்பினராக இருப்பது user authentication அல்ல; சாதாரண IP multicast தானாக reliable அல்லது confidential வழங்கலை உறுதி செய்யாது.'}},
      {heading:{en:'QoS allocates constrained service',ta:'வரம்புள்ள சேவையைப் பகிரும் QoS'},body:{en:'QoS classifies traffic and assigns queueing or scheduling treatment. DSCP marks request a class of treatment, but another administrative domain may rewrite or ignore them. Shaping delays excess traffic to fit a rate; policing typically drops or remarks traffic exceeding a profile. Priority queues can reduce delay for one class while starving others unless constrained. QoS does not increase physical capacity. Buffer size and scheduling matter because a fully utilized link can carry high throughput while imposing unacceptable latency on interactive applications.',ta:'QoS traffic-ஐ வகைப்படுத்தி queueing அல்லது scheduling கையாளுதலை ஒதுக்குகிறது. DSCP marks ஒரு வகைச் சேவையைக் கோருகின்றன; வேறு நிர்வாக domain அவற்றை மாற்றவோ புறக்கணிக்கவோலாம். Shaping rate-க்குள் பொருந்த excess traffic-ஐத் தாமதிக்கிறது; policing profile மீறும் traffic-ஐ பொதுவாக drop அல்லது remark செய்கிறது. கட்டுப்பாடின்றி priority queue ஒரு வகையின் delay-ஐக் குறைத்தபடி மற்றவற்றைச் சேவையின்றி விடலாம். QoS physical capacity-ஐ அதிகரிக்காது. Link முழுப் பயன்பாட்டில் அதிக throughput தரும்போதும் interactive applications-க்கு ஏற்கமுடியாத latency ஏற்படலாம்; buffer அளவும் scheduling-மும் முக்கியம்.'}},
      {heading:{en:'Load balancing selects service instances',ta:'Service instances தேர்ந்தெடுக்கும் load balancing'},body:{en:'A transport load balancer commonly assigns flows using endpoint information, while an application proxy can route individual requests using HTTP attributes. Connection reuse and session affinity affect distribution: equal connection counts need not mean equal backend work. Readiness checks should exercise enough dependencies to indicate useful service, whereas liveness checks answer whether a process should remain running. Removing a backend from new selection does not necessarily preserve existing sessions; draining behavior, retry safety, and shared session state need explicit design.',ta:'Transport load balancer பொதுவாக endpoint தகவலால் flows ஒதுக்குகிறது; application proxy HTTP attributes மூலம் தனி requests-ஐத் தேர்ந்தெடுக்கலாம். Connection reuse மற்றும் session affinity பகிர்வை மாற்றுகின்றன; சமமான connection எண்ணிக்கை சமமான backend வேலை அல்ல. Readiness checks பயனுள்ள சேவை கிடைப்பதைக் காட்டும் அளவு dependencies-ஐச் சோதிக்க வேண்டும். Liveness process தொடர்ந்து இயங்கலாமா என்பதைப் பார்க்கிறது. புதிய தேர்விலிருந்து backend நீக்குவது பழைய sessions-ஐ அவசியம் காப்பதில்லை; draining, பாதுகாப்பான retry, shared session state ஆகியவற்றைத் திட்டமிட வேண்டும்.'}}
    ],
    example:{en:'A 20 Mbit/s uplink receives 2 Mbit/s of voice plus 30 Mbit/s of bulk traffic. Prioritizing voice can reserve prompt service, but bulk traffic must wait, slow down, or drop; total sustained departure cannot exceed 20 Mbit/s. Independently, balancing HTTP across two backends does not expand that uplink.',ta:'20 Mbit/s uplink-க்கு 2 Mbit/s voice மற்றும் 30 Mbit/s bulk traffic வருகின்றன. Voice-க்கு முன்னுரிமை கொடுத்தால் விரைவான சேவை கிடைக்கலாம்; bulk காத்திருக்கவோ வேகம் குறையவோ drop ஆகவோ வேண்டும். தொடர்ந்து வெளியேறும் மொத்தம் 20 Mbit/s மீறாது. HTTP-ஐ இரண்டு backends-க்கு பகிர்வது uplink capacity-ஐ உயர்த்தாது.'},
    failure:{en:'A health endpoint returns 200 while real requests fail because the database is unavailable. Distinguish a live process from a ready service and test the actual dependency path. Conversely, making liveness depend on every remote dependency can cause restart storms during a shared outage.',ta:'Database கிடைக்காததால் உண்மையான requests தோல்வியடைந்தாலும் health endpoint 200 தருகிறது. உயிருடன் உள்ள process மற்றும் சேவைக்குத் தயாரான நிலையை வேறுபடுத்தி உண்மையான dependency பாதையைச் சோதிக்க வேண்டும். மறுபுறம் liveness-ஐ எல்லா remote dependency-க்கும் சார்த்தினால் பகிரப்பட்ட outage-இல் restart புயல் ஏற்படலாம்.'},
    lab:{commands:'ip maddr show\ntc -s qdisc show\nip -s link show',guidance:{en:'Read multicast memberships and queue statistics on Linux. These commands neither join new groups nor replace queue disciplines. Compare packet and drop counters over an observed interval; cumulative totals without elapsed time cannot establish a current loss rate.',ta:'Linux-இல் multicast memberships மற்றும் queue புள்ளிவிவரங்களை வாசியுங்கள். இவை புதிய group-இல் சேரவோ queue discipline-ஐ மாற்றவோ செய்யாது. குறிப்பிட்ட இடைவெளியில் packet, drop counters-ஐ ஒப்பிடுங்கள்; கடந்த நேரம் இல்லாத மொத்த எண்ணிக்கை தற்போதைய loss rate-ஐ நிறுவாது.'},expected:{en:'Memberships and queue disciplines vary by host. Missing drops in one software queue do not rule out congestion elsewhere in the path or in hardware.',ta:'Host-க்கு ஏற்ப memberships, queue disciplines மாறும். ஒரு software queue-இல் drops இல்லாதது வேறு பாதைப் பகுதி அல்லது hardware-இல் congestion இல்லை என்பதல்ல.'},cleanup:{en:'No memberships, queues, or backend settings were modified.',ta:'Memberships, queues, backend அமைப்புகள் மாற்றப்படவில்லை.'}},
    questions:[
      {question:{en:'What does IGMP primarily signal?',ta:'IGMP முக்கியமாக எதைத் தெரிவிக்கிறது?'},options:{en:['IPv4 multicast group membership','HTTP authentication','BGP local preference'],ta:['IPv4 multicast group membership','HTTP authentication','BGP local preference']},answer:0,explanation:{en:'Membership signaling differs from inter-router multicast route construction.',ta:'Membership signaling மற்றும் routers இடையிலான multicast route அமைத்தல் வேறு.'}},
      {question:{en:'A 10 Mbit/s link receives 14 Mbit/s steadily. What can QoS do?',ta:'10 Mbit/s link-க்கு தொடர்ந்து 14 Mbit/s வருகிறது. QoS என்ன செய்யலாம்?'},options:{en:['Choose which traffic waits or drops within 10 Mbit/s','Deliver all 14 Mbit/s indefinitely','Create 4 Mbit/s with DSCP'],ta:['10 Mbit/s வரம்புக்குள் எது காத்திருக்க அல்லது drop ஆக வேண்டும் எனத் தேர்வு செய்யலாம்','14 Mbit/s முழுவதையும் முடிவின்றி வழங்கலாம்','DSCP மூலம் 4 Mbit/s உருவாக்கலாம்']},answer:0,explanation:{en:'Sustained excess cannot fit into finite buffers forever.',ta:'தொடர்ச்சியான அதிக வரவை வரம்புள்ள buffers முடிவின்றி வைத்திருக்க முடியாது.'}},
      {question:{en:'Why can equal connection counts produce unequal backend load?',ta:'சம connection எண்ணிக்கையிலும் backend load ஏன் வேறுபடலாம்?'},options:{en:['Connections can carry different amounts of work','Every connection has identical requests','DNS forces equal CPU time'],ta:['Connections வெவ்வேறு அளவு வேலை எடுத்துச் செல்லலாம்','ஒவ்வொரு connection-க்கும் ஒரே requests','DNS சம CPU நேரத்தை கட்டாயப்படுத்துகிறது']},answer:0,explanation:{en:'Long-lived and reused connections can carry many uneven requests.',ta:'நீண்டநாள் மற்றும் மீள்பயன்பாட்டு connections சமமற்ற பல requests-ஐச் சுமக்கலாம்.'}}
    ],refs:[['Differentiated services — RFC 2475','https://www.rfc-editor.org/rfc/rfc2475.html'],['IGMPv3 — RFC 3376','https://www.rfc-editor.org/rfc/rfc3376.html'],['Kubernetes probes','https://kubernetes.io/docs/concepts/configuration/liveness-readiness-startup-probes/']]
  },
  {
    id:25,module:6,model:'firewall',title:{en:'Firewalls, VPNs & trust boundaries',ta:'Firewalls, VPNs மற்றும் நம்பிக்கை எல்லைகள்'},
    summary:{en:'Design explicit traffic policy and understand what tunnel encryption does and does not authorize.',ta:'Traffic-க்கான வெளிப்படையான policy அமைத்து tunnel encryption எதற்கு அனுமதி அளிக்கிறது, அதன் வரம்பு என்ன என்பதைப் புரிந்துகொள்ளுங்கள்.'},
    prerequisites:{en:'Know routes, ports, transport state, NAT, and the difference between authentication and authorization.',ta:'Routes, ports, transport state, NAT, authentication மற்றும் authorization வேறுபாடு தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Locate local-input and forwarded traffic policy.','Trace inner and outer tunnel packets.','Define tests for allowed and denied access without risking remote lockout.'],ta:['Local-input மற்றும் forwarded traffic policy இடங்களைக் கண்டறிதல்.','Tunnel-இன் inner, outer packets-ஐப் பின்தொடர்தல்.','Remote அணுகலை இழக்காமல் அனுமதி, மறுப்பு சோதனைகளை வரையறுத்தல்.']},
    sections:[
      {heading:{en:'Rules apply at particular boundaries',ta:'குறிப்பிட்ட எல்லைகளில் பொருந்தும் rules'},body:{en:'A packet filter evaluates fields such as addresses, protocol, interfaces, and connection state. Traffic addressed to the firewall host follows a different path from traffic forwarded through it, so an input allow rule does not necessarily permit transit traffic. Stateful tracking can recognize replies to permitted connections, but state is not an application identity. Rule ordering, hook priority, default policy, and translation placement affect the final result. Read the active ruleset and management ownership before proposing changes; multiple tools can manage the same underlying filter.',ta:'Packet filter address, protocol, interface, connection state போன்ற fields-ஐ மதிப்பிடுகிறது. Firewall host-க்கே வந்த traffic மற்றும் அதன் வழியாக forward ஆகும் traffic வேறு பாதைகளைக் கடக்கும்; input allow rule transit traffic-ஐ அவசியம் அனுமதிக்காது. Stateful tracking அனுமதித்த connection-இன் replies-ஐ அறியலாம்; state என்பது application அடையாளமல்ல. Rule வரிசை, hook priority, default policy, translation இடம் முடிவை மாற்றுகின்றன. மாற்றம் பரிந்துரைக்குமுன் active ruleset மற்றும் நிர்வாக உரிமையைப் பாருங்கள்; பல tools ஒரே அடிப்படை filter-ஐ நிர்வகிக்கலாம்.'}},
      {heading:{en:'VPN routes and encapsulation',ta:'VPN routes மற்றும் encapsulation'},body:{en:'A VPN carries an inner packet inside an outer transport across an underlay. IPsec defines security associations and packet protection mechanisms; deployment also needs suitable key management and peer authentication. Split tunneling sends selected destinations through the tunnel, whereas full-tunnel configurations attempt to carry broader traffic. DNS and IPv6 behavior must be checked separately rather than inferred from one IPv4 default route. Encapsulation consumes MTU space, so working small probes alongside stalled larger transfers can indicate a path-size problem.',ta:'VPN inner packet-ஐ outer transport-க்குள் வைத்து underlay வழியாக எடுத்துச் செல்கிறது. IPsec security associations மற்றும் packet பாதுகாப்பு முறைகளை வரையறுக்கிறது; சரியான key management, peer authentication ஆகியவையும் தேவை. Split tunneling தேர்ந்தெடுத்த destinations-ஐ tunnel வழி அனுப்புகிறது; full-tunnel அமைப்புகள் பரந்த traffic-ஐ எடுத்துச் செல்ல முயல்கின்றன. ஒரு IPv4 default route-இலிருந்து ஊகிக்காமல் DNS, IPv6 செயல்பாட்டைத் தனியாகச் சோதிக்க வேண்டும். Encapsulation MTU இடத்தைப் பயன்படுத்தும்; சிறிய probes இயங்கி பெரிய transfers நின்றால் path-size சிக்கல் இருக்கலாம்.'}},
      {heading:{en:'Trust remains scoped',ta:'வரம்புடன் இருக்கும் நம்பிக்கை'},body:{en:'A tunnel authenticates configured peers and protects selected transit traffic, but the remote endpoint can see traffic after decryption. Applications still need user identity, authorization, and secure data handling. A private address or VPN connection should not imply unrestricted access to every service. Express policy as a matrix of source role, destination service, protocol, and required identity. Include negative tests and a recovery path for administration; a default-deny policy is useful only when legitimate dependencies and emergency access have been considered.',ta:'Tunnel அமைக்கப்பட்ட peers-ஐ உறுதிப்படுத்தி தேர்ந்தெடுத்த transit traffic-ஐப் பாதுகாக்கிறது; decrypt ஆனபின் remote endpoint traffic-ஐப் பார்க்கலாம். Applications-க்கு இன்னும் user identity, authorization, பாதுகாப்பான தரவு கையாளுதல் தேவை. Private address அல்லது VPN connection எல்லாச் சேவைக்கும் வரம்பற்ற அனுமதியாகக் கருதப்படக் கூடாது. Source பணி, destination service, protocol, தேவையான identity ஆகியவற்றைக் கொண்ட matrix-ஆக policy எழுதுங்கள். Negative tests மற்றும் நிர்வாக recovery வழியைச் சேர்க்க வேண்டும்; legitimate dependencies, அவசர அணுகல் ஆகியவற்றைக் கணக்கில் கொண்டால்தான் default-deny பயனுள்ளதாகும்.'}}
    ],
    example:{en:'Guests may use DNS at a designated resolver and HTTPS to the Internet, but must not reach the administration subnet. A staff VPN permits one management service only after user authorization. The outer VPN port is allowed at the perimeter; inner access is evaluated separately, so allowing tunnel setup does not permit every inner destination.',ta:'Guest-கள் குறிப்பிட்ட resolver-இல் DNS மற்றும் Internet-க்கு HTTPS பயன்படுத்தலாம்; administration subnet அணுகக் கூடாது. Staff VPN user authorization-க்குப் பிறகு ஒரு management service மட்டும் அனுமதிக்கிறது. Perimeter-இல் outer VPN port அனுமதிக்கப்படுகிறது; inner அணுகல் தனியாக மதிப்பிடப்படுகிறது. Tunnel தொடங்க அனுமதி என்பது எல்லா inner destinations-க்கும் அனுமதி அல்ல.'},
    failure:{en:'A VPN connects, yet an internal application times out. Inspect inner routes, forwarded policy, DNS selection, MTU, and application permissions instead of repeatedly changing tunnel keys. If a remote firewall edit is eventually needed, first prepare a verified rollback and an independent administration path.',ta:'VPN இணைந்தாலும் உள் application timeout ஆகிறது. Tunnel keys-ஐ மீண்டும் மாற்றாமல் inner routes, forwarding policy, DNS தேர்வு, MTU, application permissions ஆகியவற்றைப் பாருங்கள். பின்னர் remote firewall மாற்றம் தேவைப்பட்டால் முதலில் சரிபார்த்த rollback மற்றும் தனி நிர்வாகப் பாதை தயாரிக்க வேண்டும்.'},
    lab:{commands:'ip -4 route show\nip -6 route show\nip rule show\nss -tuln\nif command -v nft >/dev/null; then sudo nft list ruleset; fi',guidance:{en:'Inspect a machine you administer. Compare these views before and during an existing authorized VPN session if one is already available. Do not enable a firewall, flush rules, or create a tunnel for this lab. Keep sensitive policy output private.',ta:'நீங்கள் நிர்வகிக்கும் கணினியைப் பாருங்கள். ஏற்கெனவே அனுமதிக்கப்பட்ட VPN இருந்தால் அதற்கு முன்பும் அதன் போதும் இந்த நிலைகளை ஒப்பிடுங்கள். Lab-க்காக firewall enable, rules flush, tunnel உருவாக்குதல் செய்ய வேண்டாம். Policy வெளியீட்டைத் தனிப்பட்டதாக வைத்திருங்கள்.'},expected:{en:'Identify which prefixes and interfaces use the tunnel and where input or forward policy is attached. An absent IPv6 tunnel route deserves separate explanation rather than an assumption of protection.',ta:'எந்த prefixes, interfaces tunnel பயன்படுத்துகின்றன, input அல்லது forward policy எங்கே உள்ளது என்று கண்டறியுங்கள். IPv6 tunnel route இல்லாததை பாதுகாப்பு உள்ளது என்று ஊகிக்காமல் தனியாக விளக்க வேண்டும்.'},cleanup:{en:'Read-only inspection requires no rule or route cleanup.',ta:'வாசிப்பு மட்டும் என்பதால் rule அல்லது route அகற்றுதல் தேவையில்லை.'}},
    questions:[
      {question:{en:'Does allowing the VPN outer port authorize every inner service?',ta:'VPN outer port அனுமதி எல்லா inner services-க்கும் உரிமையா?'},options:{en:['No; inner policy and application authorization remain','Yes; encryption grants all permissions','Only for private IPv4'],ta:['இல்லை; inner policy, application authorization இன்னும் தேவை','ஆம்; encryption எல்லா உரிமையும் தரும்','Private IPv4-க்கு மட்டும்']},answer:0,explanation:{en:'Transport establishment and service authorization are separate decisions.',ta:'Transport தொடங்குதலும் service அனுமதியும் தனி முடிவுகள்.'}},
      {question:{en:'Small tunnel packets work but large transfers stall. Which hypothesis deserves testing?',ta:'சிறிய tunnel packets இயங்குகின்றன; பெரிய transfer நிற்கிறது. எந்தக் காரணத்தைச் சோதிக்க வேண்டும்?'},options:{en:['Encapsulation MTU and path MTU signaling','The password must be wrong','DNS always fragments TCP'],ta:['Encapsulation MTU மற்றும் path MTU signaling','Password கட்டாயம் தவறு','DNS எப்போதும் TCP-ஐ fragment செய்கிறது']},answer:0,explanation:{en:'Outer headers reduce available inner-packet space.',ta:'Outer headers inner packet-க்கு கிடைக்கும் இடத்தைக் குறைக்கின்றன.'}},
      {question:{en:'Which policy path normally handles packets routed through a Linux firewall?',ta:'Linux firewall வழியாக route செய்யப்படும் packets வழக்கமாக எந்த policy பாதையில் செல்கின்றன?'},options:{en:['Forwarding path','Only local input','Only an HTTP cookie policy'],ta:['Forwarding பாதை','Local input மட்டும்','HTTP cookie policy மட்டும்']},answer:0,explanation:{en:'Transit packets are distinct from packets addressed to the firewall itself.',ta:'கடந்து செல்லும் packets மற்றும் firewall-க்கே வரும் packets வேறுபட்டவை.'}}
    ],refs:[['IPsec architecture — RFC 4301','https://www.rfc-editor.org/rfc/rfc4301.html'],['nftables manual','https://netfilter.org/projects/nftables/manpage.html'],['Zero Trust Architecture — NIST SP 800-207','https://csrc.nist.gov/pubs/sp/800/207/final']]
  },
  {
    id:26,module:6,model:'capture',title:{en:'Packet capture & systematic troubleshooting',ta:'Packet capture மற்றும் முறையான சிக்கல் கண்டறிதல்'},
    summary:{en:'Use layered hypotheses and capture evidence to locate failures before changing configuration.',ta:'Configuration மாற்றுமுன் layer அடிப்படையிலான கருதுகோள்களும் capture ஆதாரங்களும் கொண்டு தோல்வி இடத்தைக் கண்டறியுங்கள்.'},
    prerequisites:{en:'Recognize DNS requests, TCP flags, IP routes, and the distinction between host and network failures.',ta:'DNS requests, TCP flags, IP routes, host மற்றும் network தோல்வி வேறுபாடு ஆகியவை தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Build a reproducible symptom report.','Choose capture filters and interpret visibility limits.','Distinguish retransmission, reset, and application failure evidence.'],ta:['மீண்டும் உருவாக்கக்கூடிய அறிகுறி அறிக்கை தயாரித்தல்.','Capture filters தேர்ந்து பார்வையின் வரம்பைப் புரிந்துகொள்ளுதல்.','Retransmission, reset, application failure ஆதாரங்களை வேறுபடுத்துதல்.']},
    sections:[
      {heading:{en:'Start with a falsifiable hypothesis',ta:'சோதித்து மறுக்கக்கூடிய கருதுகோளில் தொடங்குதல்'},body:{en:'Record the exact application operation, endpoint, time, error, and affected scope. Compare a failing client with a working one where possible. Check link, address, route, neighbor state, DNS, transport, and application response in an order guided by the symptom. Each observation should narrow a hypothesis: a successful DNS answer does not prove TCP connectivity, and a successful handshake does not prove HTTP authorization. Change one relevant variable at a time and repeat the original user operation after a proposed repair.',ta:'Application செயல், endpoint, நேரம், error, பாதிக்கப்பட்ட அளவு ஆகியவற்றைத் துல்லியமாகப் பதிவு செய்யுங்கள். முடிந்தால் தோல்வி client-ஐ இயங்கும் client உடன் ஒப்பிடுங்கள். அறிகுறிக்கேற்ற வரிசையில் link, address, route, neighbor நிலை, DNS, transport, application response பாருங்கள். ஒவ்வொரு கண்டுபிடிப்பும் கருதுகோளைச் சுருக்க வேண்டும். DNS விடை வந்தது TCP தொடர்பை நிரூபிக்காது; handshake வெற்றி HTTP அனுமதியை நிரூபிக்காது. ஒரே நேரத்தில் ஒரு தொடர்புடைய காரணியை மாற்றி, தீர்வுக்குப் பிறகு உண்மையான பயனர் செயலை மீண்டும் சோதியுங்கள்.'}},
      {heading:{en:'Capture filters and display filters',ta:'Capture filters மற்றும் display filters'},body:{en:'A capture filter chooses what is retained at collection time; a Wireshark display filter selects from packets already collected. The expressions tcp port 443 and tcp.port == 443 belong to different languages. Pick the interface and observation point deliberately: a capture on the client cannot directly reveal a packet dropped before reaching the server. Snap length, capture loss, and storage limits can remove evidence. Captures may contain secrets even when most payload is encrypted, so limit collection and retain only authorized diagnostic material.',ta:'Capture filter சேகரிக்கும் நேரத்தில் எதை வைத்துக்கொள்ள வேண்டும் என்று தேர்கிறது. Wireshark display filter ஏற்கெனவே சேகரித்த packets-இல் தேர்கிறது. tcp port 443 மற்றும் tcp.port == 443 வெவ்வேறு மொழிகளின் expressions. Interface, observation point ஆகியவற்றைத் திட்டமிட்டுத் தேர்ந்தெடுங்கள்; client capture server வருமுன் drop ஆன இடத்தை நேரடியாகக் காட்டாது. Snap length, capture loss, storage வரம்பு ஆதாரத்தை நீக்கலாம். பெரும்பாலான payload encrypt ஆனாலும் capture-இல் ரகசியங்கள் இருக்கலாம்; சேகரிப்பைக் குறைத்து அனுமதித்த ஆய்வுத் தகவலை மட்டும் வைத்திருங்கள்.'}},
      {heading:{en:'Interpret traces without overclaiming',ta:'அளவுக்கு மீறாத trace விளக்கம்'},body:{en:'Repeated SYNs without a visible SYN-ACK are consistent with loss, filtering, a wrong address, or missing return traffic; they do not identify a particular firewall by themselves. A reset is an explicit transport response but can originate from an endpoint or intermediary. Local checksum offload may expose outgoing packets before hardware computes checksums, and segmentation offload can change observed packet sizes. Encrypted application content requires appropriate authorized session secrets for decryption; a packet analyzer cannot recover it simply by selecting a protocol filter.',ta:'SYN-ACK தெரியாமல் மீண்டும் SYN வருவது loss, filtering, தவறான address அல்லது திரும்பும் traffic இல்லாமையுடன் பொருந்தலாம்; குறிப்பிட்ட firewall-ஐ மட்டும் அது அடையாளப்படுத்தாது. Reset வெளிப்படையான transport response; endpoint அல்லது intermediary அனுப்பலாம். Hardware checksum கணக்கிடுமுன் outgoing packet capture ஆகலாம் என்பதால் checksum offload தவறான தோற்றம் தரலாம்; segmentation offload காணப்படும் packet அளவையும் மாற்றலாம். Encrypt ஆன application content-ஐ decrypt செய்ய அனுமதிக்கப்பட்ட session secrets தேவை; protocol filter தேர்வால் மட்டும் analyzer அதைப் பெறாது.'}}
    ],
    example:{en:'DNS resolves successfully. The trace shows SYN, SYN-ACK, ACK, then a TLS handshake and an HTTP 403 visible in the client’s decrypted application log. Lower-layer delivery worked far enough for the server to deny the request. Investigate application authorization rather than changing the gateway or DNS server.',ta:'DNS வெற்றி. Trace-இல் SYN, SYN-ACK, ACK, பின்னர் TLS handshake உள்ளது; client application log-இல் decrypt செய்யப்பட்ட HTTP 403 தெரிகிறது. Server request-ஐ மறுக்கும் அளவு lower layers இயங்கியுள்ளன. Gateway அல்லது DNS மாற்றாமல் application authorization-ஐ ஆராய வேண்டும்.'},
    failure:{en:'A short capture has no DNS packets, so an operator concludes DNS was bypassed maliciously. The answer may already be cached, or resolution may use encrypted transport. Establish capture timing and resolver behavior first; absence from this observation point is weaker than proof of nonexistence.',ta:'குறுகிய capture-இல் DNS packets இல்லாததால் தீங்காக DNS தவிர்க்கப்பட்டது என்று முடிவெடுக்கப்படுகிறது. விடை cache-இல் இருக்கலாம் அல்லது resolution encrypt செய்யப்பட்ட transport பயன்படுத்தலாம். முதலில் capture நேரம், resolver செயல்பாடு ஆகியவற்றை நிறுவுங்கள்; ஒரு பார்வை இடத்தில் இல்லாதது முழுவதும் இல்லை என்பதற்கான நிரூபணம் அல்ல.'},
    lab:{commands:'ip -br addr\nip route\nip neigh\ndig example.com A\ncurl --max-time 15 -vI https://example.com\nss -tan\nif command -v tcpdump >/dev/null; then sudo timeout 5 tcpdump -ni lo -c 4 "icmp" & cap_pid=$!; ping -c 2 127.0.0.1; wait "$cap_pid"; fi',guidance:{en:'Use Linux, dig, curl, ping, and optionally tcpdump plus GNU timeout. The bounded optional capture observes loopback ICMP only and writes no PCAP. Capture startup can race with ping; if fewer packets appear, explain timing rather than declaring packet loss.',ta:'Linux, dig, curl, ping மற்றும் விருப்பமாக tcpdump, GNU timeout தேவை. வரம்பிட்ட capture loopback ICMP மட்டும் பார்த்து PCAP எழுதாது. Capture தொடங்கும் நேரத்துக்கு முன்பே ping செல்லலாம்; குறைவான packets தெரிந்தால் உடனே loss எனாமல் timing-ஐ விளக்குங்கள்.'},expected:{en:'Produce an evidence log separating lookup, transport, and application outcomes. Loopback replies prove a local stack exchange, not Internet reachability.',ta:'Lookup, transport, application முடிவுகளைத் தனியாகக் கொண்ட ஆதாரப் பதிவு உருவாக்குங்கள். Loopback replies local stack பரிமாற்றத்தை மட்டுமே நிரூபிக்கும்; Internet தொடர்பை அல்ல.'},cleanup:{en:'The capture stops after its packet limit or timeout. No persistent capture file exists.',ta:'Packet வரம்பு அல்லது timeout வந்தால் capture நிற்கும். நிரந்தர capture கோப்பு இல்லை.'}},
    questions:[
      {question:{en:'Which expression is a Wireshark display filter?',ta:'Wireshark display filter expression எது?'},options:{en:['tcp.port == 443','tcp port 443','route via 443'],ta:['tcp.port == 443','tcp port 443','route via 443']},answer:0,explanation:{en:'The dotted field comparison is display-filter syntax.',ta:'புள்ளியுடன் field-ஐ ஒப்பிடுவது display-filter syntax.'}},
      {question:{en:'Three SYNs and no observed reply prove what?',ta:'மூன்று SYN; reply தெரியவில்லை. இது எதை நிரூபிக்கிறது?'},options:{en:['This capture lacks a visible reply; more localization is needed','The server firewall definitely dropped them','DNS is definitely wrong'],ta:['இந்த capture-இல் reply தெரியவில்லை; மேலும் இடம் கண்டறிதல் தேவை','Server firewall நிச்சயம் drop செய்தது','DNS நிச்சயம் தவறு']},answer:0,explanation:{en:'Multiple loss, filtering, routing, and observation explanations remain possible.',ta:'Loss, filtering, routing, பார்வை வரம்பு ஆகிய பல விளக்கங்கள் இன்னும் சாத்தியம்.'}},
      {question:{en:'Outgoing checksums look bad only on a local capture. What should be checked?',ta:'Local capture-இல் மட்டும் outgoing checksums தவறாகத் தெரிகின்றன. எதைப் பார்க்க வேண்டும்?'},options:{en:['Checksum offload and capture location','Immediately replace every cable','Assume TLS corruption'],ta:['Checksum offload மற்றும் capture இடம்','உடனே எல்லா cable-களையும் மாற்றுதல்','TLS corruption என்று கருதுதல்']},answer:0,explanation:{en:'Hardware may fill the checksum after the software capture point.',ta:'Software capture இடத்துக்குப் பிறகு hardware checksum நிரப்பலாம்.'}}
    ],refs:[['Wireshark user guide','https://www.wireshark.org/docs/wsug_html_chunked/'],['tcpdump manual','https://www.tcpdump.org/manpages/tcpdump.1.html'],['Linux segmentation offloads','https://docs.kernel.org/networking/segmentation-offloads.html']]
  },
  {
    id:27,module:6,model:'security',title:{en:'Threat models & resilient network design',ta:'Threat models மற்றும் மீள்திறனுள்ள network வடிவமைப்பு'},
    summary:{en:'Match concrete threats to preventive, detective, and recovery controls with testable limits.',ta:'குறிப்பிட்ட அச்சுறுத்தல்களுக்கு தடுப்பு, கண்டறிதல், மீட்பு கட்டுப்பாடுகளைச் சோதிக்கக்கூடிய வரம்புகளுடன் இணைக்குங்கள்.'},
    prerequisites:{en:'Understand authentication, segmentation, DNS/TLS roles, firewall policy, and common service dependencies.',ta:'Authentication, segmentation, DNS/TLS பணிகள், firewall policy, பொதுவான service dependencies ஆகியவை தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Write an asset-and-boundary threat model.','Choose controls for specific attacker capabilities.','Evaluate recovery objectives and shared failure modes.'],ta:['Assets மற்றும் boundaries அடிப்படையில் threat model எழுதுதல்.','தாக்குபவரின் குறிப்பிட்ட திறன்களுக்கு ஏற்ற controls தேர்ந்தெடுத்தல்.','Recovery இலக்குகள், பகிரப்பட்ட failure காரணிகளை மதிப்பிடுதல்.']},
    sections:[
      {heading:{en:'Assets, adversaries, and assumptions',ta:'Assets, எதிரிகள் மற்றும் ஊகங்கள்'},body:{en:'Begin with what must be protected: service availability, private records, administrative control, or integrity of updates. Describe plausible attacker access, such as an untrusted guest device, stolen account, or upstream traffic source. Mark boundaries where identity and authorization are checked. Distinguish a protocol weakness from an implementation bug or operational mistake. Local ARP spoofing and remote volumetric denial of service require different capabilities and defenses. Record assumptions explicitly, because a design for an isolated classroom is not automatically suitable for a public service.',ta:'சேவை கிடைப்பது, தனிப்பட்ட பதிவுகள், நிர்வாகக் கட்டுப்பாடு, updates மாற்றமின்மை ஆகியவற்றில் எதைப் பாதுகாக்க வேண்டும் என்று தொடங்குங்கள். நம்பாத guest சாதனம், திருடப்பட்ட account, upstream traffic source போன்ற தாக்குபவர் அணுகலை விவரியுங்கள். Identity, authorization சோதிக்கப்படும் boundaries-ஐக் குறியுங்கள். Protocol பலவீனம், implementation bug, நிர்வாகத் தவறு ஆகியவற்றை வேறுபடுத்துங்கள். Local ARP spoofing மற்றும் தொலைவிலிருந்து volumetric denial of service வெவ்வேறு திறன்களையும் பாதுகாப்புகளையும் தேவைப்படுத்தும். ஊகங்களை வெளிப்படையாக எழுதுங்கள்; தனிமைப்படுத்திய வகுப்பறை வடிவமைப்பு public service-க்கு தானாகப் பொருந்தாது.'}},
      {heading:{en:'Layered controls and useful observation',ta:'பல அடுக்கு controls மற்றும் பயனுள்ள கண்காணிப்பு'},body:{en:'Minimize exposed listeners, patch software, separate roles with least-privilege access, and authenticate administration. Encryption protects selected communication paths but does not prevent a compromised endpoint from using valid credentials. Rate limits can reduce expensive request processing, while an upstream link saturated by unwanted traffic may need provider-side help. Logs should record reliable timestamps, relevant identities, and decision outcomes without unnecessary secrets. Monitoring needs an expected baseline and an actionable response; collecting large volumes of events alone does not establish detection capability.',ta:'வெளியே தெரியும் listeners-ஐக் குறைத்து software patch செய்து குறைந்த உரிமையுடன் roles பிரித்து நிர்வாக அடையாளத்தைச் சோதியுங்கள். Encryption குறிப்பிட்ட தொடர்புப் பாதைகளைப் பாதுகாக்கும்; பாதிக்கப்பட்ட endpoint சரியான credentials பயன்படுத்துவதைத் தடுக்காது. Rate limits விலையுயர்ந்த request செயலாக்கத்தைக் குறைக்கலாம்; தேவையற்ற traffic upstream link-ஐ நிரப்பினால் provider உதவி தேவைப்படலாம். Logs-இல் சரியான timestamps, தொடர்புடைய identities, முடிவுகள் இருக்க வேண்டும்; தேவையற்ற ரகசியங்கள் வேண்டாம். Monitoring-க்கு வழக்கமான baseline மற்றும் செயல்படுத்தக்கூடிய பதில் தேவை; பெருமளவு events சேகரிப்பது மட்டும் detection திறனை நிறுவாது.'}},
      {heading:{en:'Recovery is part of security',ta:'Security-இன் பகுதியாக recovery'},body:{en:'Define recovery time objective as a target for restoring service and recovery point objective as a target for tolerable data loss measured in time. Test restores, credential recovery, and dependency availability rather than checking only that backup jobs completed. Two uplinks sharing a conduit, power feed, or upstream provider can fail together. Redundancy helps only against the failures it actually separates. Exercises should include degraded operation, rollback, and communication responsibilities, with measured results compared against the declared objectives instead of a claim of perfect availability.',ta:'Recovery time objective சேவை மீட்க வேண்டிய நேர இலக்கு; recovery point objective கால அளவில் பொறுத்துக்கொள்ளக்கூடிய data loss இலக்கு. Backup job முடிந்ததா என்பதை மட்டும் பார்க்காமல் restore, credential recovery, dependency கிடைப்பைச் சோதியுங்கள். இரண்டு uplinks ஒரே conduit, மின்சாரம், upstream provider பகிர்ந்தால் ஒன்றாகத் தோல்வியடையலாம். Redundancy உண்மையில் பிரித்த failure-களுக்கே உதவும். பயிற்சியில் குறைந்த சேவை நிலை, rollback, தகவல்தொடர்பு பொறுப்புகள் இடம்பெற வேண்டும்; முழுமையான availability என்று கூறாமல் அளந்த முடிவுகளை அறிவித்த இலக்குகளுடன் ஒப்பிட வேண்டும்.'}}
    ],
    example:{en:'A small service targets RTO 30 minutes and RPO 10 minutes. Backups occur every hour, and a restore drill takes 45 minutes. The demonstrated process misses both targets: potential data loss approaches an hour and restoration exceeds 30 minutes. Improve the process and repeat the drill before advertising those objectives as achieved.',ta:'ஒரு சேவையின் RTO 30 நிமிடம்; RPO 10 நிமிடம். Backup மணிக்கொரு முறை; restore பயிற்சி 45 நிமிடம். காட்டப்பட்ட செயல்முறை இரு இலக்குகளையும் தவறுகிறது: data loss ஒரு மணி நேரத்தை நெருங்கலாம்; மீட்பு 30 நிமிடத்தை மீறுகிறது. செயல்முறையை மேம்படுத்தி மீண்டும் சோதித்தபின் மட்டுமே இலக்குகள் எட்டப்பட்டதாகக் கூற வேண்டும்.'},
    failure:{en:'Two backup servers use the same privileged account and online storage. A stolen credential deletes both production and backups. Separate administration and recovery access, protect an appropriate independent copy, and test restoration from it. Mere duplication did not separate the credential failure domain.',ta:'இரண்டு backup servers ஒரே privileged account மற்றும் online storage பயன்படுத்துகின்றன. திருடப்பட்ட credential production, backups இரண்டையும் அழிக்கிறது. நிர்வாகம், recovery அணுகலைப் பிரித்து பொருத்தமான தனி நகலைப் பாதுகாத்து அதிலிருந்து restore சோதிக்க வேண்டும். நகல் எண்ணிக்கை மட்டும் credential failure domain-ஐப் பிரிக்கவில்லை.'},
    lab:{commands:'ss -tuln\ndate -u\nip -br addr\nip route show',guidance:{en:'Inventory only your own host. For each listener, document intended clients, required identity, data exposure, and owner where known. Pair the inventory with a written recovery exercise plan; these inspection commands do not perform a backup, failover, or attack simulation.',ta:'உங்கள் host-ஐ மட்டும் inventory செய்யுங்கள். ஒவ்வொரு listener-க்கும் நோக்கமுள்ள clients, தேவையான identity, தரவு வெளிப்பாடு, தெரிந்தால் owner ஆகியவற்றை எழுதுங்கள். இதனுடன் recovery பயிற்சித் திட்டம் எழுதுங்கள்; இந்த commands backup, failover, தாக்குதல் simulation செய்யாது.'},expected:{en:'Produce a short control-to-threat mapping and identify one shared dependency. Unknown listeners are investigation items, not automatic evidence of intrusion.',ta:'Threat-க்கு control இணைப்புப் பட்டியலும் ஒரு பகிரப்பட்ட dependency-யும் உருவாக்குங்கள். தெரியாத listeners விசாரிக்க வேண்டியவை; தானாக intrusion ஆதாரம் அல்ல.'},cleanup:{en:'No services were disabled or reconfigured.',ta:'சேவைகள் நிறுத்தப்படவோ மாற்றப்படவோ இல்லை.'}},
    questions:[
      {question:{en:'What should a threat model identify first?',ta:'Threat model முதலில் எதை அடையாளப்படுத்த வேண்டும்?'},options:{en:['Assets, plausible attacker capabilities, and boundaries','A product to buy regardless of context','Only encryption algorithms'],ta:['Assets, சாத்தியமான attacker திறன்கள், boundaries','சூழல் பார்க்காமல் வாங்க வேண்டிய product','Encryption algorithms மட்டும்']},answer:0,explanation:{en:'Controls need a concrete protection goal and threat context.',ta:'Controls-க்கு குறிப்பிட்ட பாதுகாப்பு இலக்கும் அச்சுறுத்தல் சூழலும் தேவை.'}},
      {question:{en:'Hourly backups alone meet an RPO of five minutes?',ta:'மணிக்கொரு backup மட்டும் ஐந்து நிமிட RPO-ஐப் பூர்த்தி செய்யுமா?'},options:{en:['No; recoverable data can be much older','Yes; backup existence is enough','Yes if there are two routers'],ta:['இல்லை; மீட்கும் தரவு மிகவும் பழையதாகலாம்','ஆம்; backup இருப்பதே போதும்','இரண்டு routers இருந்தால் ஆம்']},answer:0,explanation:{en:'Recovery point concerns data freshness, not just a successful job.',ta:'Recovery point தரவின் புதுமையைப் பற்றியது; job வெற்றியை மட்டும் அல்ல.'}},
      {question:{en:'Two links share one conduit. Which risk remains?',ta:'இரண்டு links ஒரே conduit பகிர்கின்றன. எந்த ஆபத்து மீதமுள்ளது?'},options:{en:['A single physical event can break both','All failures are now independent','TLS prevents cable damage'],ta:['ஒரே உடல் நிகழ்வு இரண்டையும் துண்டிக்கலாம்','எல்லா failures-மும் இப்போது தனித்தனி','TLS cable சேதத்தைத் தடுக்கிறது']},answer:0,explanation:{en:'A shared physical path is a common failure dependency.',ta:'பகிரப்பட்ட உடல் பாதை பொதுவான failure dependency.'}}
    ],refs:[['Security glossary — RFC 4949','https://www.rfc-editor.org/rfc/rfc4949.html'],['Contingency planning — NIST SP 800-34 Rev. 1','https://csrc.nist.gov/pubs/sp/800/34/r1/final'],['Zero Trust Architecture — NIST SP 800-207','https://csrc.nist.gov/pubs/sp/800/207/final']]
  },
  {
    id:28,module:7,model:'namespaces',title:{en:'Linux namespaces & container networking',ta:'Linux namespaces மற்றும் container networking'},
    summary:{en:'Build two isolated network stacks and relate veth, bridge, routing, and container service abstractions.',ta:'இரண்டு தனிமைப்படுத்திய network stacks உருவாக்கி veth, bridge, routing, container service கருத்துகளுடன் இணைத்துப் புரிந்துகொள்ளுங்கள்.'},
    prerequisites:{en:'Use Linux iproute2, assign IPv4 prefixes, and distinguish layer-2 bridging from layer-3 routing.',ta:'Linux iproute2 பயன்படுத்தவும் IPv4 prefixes ஒதுக்கவும் layer-2 bridging, layer-3 routing வேறுபாட்டைப் புரிந்துகொள்ளவும் தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Explain which network state a namespace isolates.','Create and remove an isolated veth experiment.','Distinguish container addresses, services, and network policy.'],ta:['Namespace எந்த network நிலையைப் பிரிக்கிறது என விளக்குதல்.','தனிமைப்படுத்திய veth பயிற்சியை உருவாக்கி அகற்றுதல்.','Container addresses, services, network policy-ஐ வேறுபடுத்துதல்.']},
    sections:[
      {heading:{en:'Independent stacks on one kernel',ta:'ஒரே kernel-இல் தனித்தனி stacks'},body:{en:'A network namespace isolates interfaces, protocol stacks, routing tables, sockets, and associated network configuration. It shares the host kernel; it is not a separate virtual machine or a complete security boundary by itself. Each namespace has its own loopback interface, initially down in a newly created namespace. A process executes in one network context and observes that context’s interfaces and routes. Namespace isolation is different from filesystem isolation, so an application can share files while seeing a different network.',ta:'Network namespace interfaces, protocol stacks, routing tables, sockets மற்றும் தொடர்புடைய network அமைப்புகளைப் பிரிக்கிறது. Host kernel பகிரப்படுகிறது; இது தனி virtual machine அல்லது தனித்து முழு security boundary அல்ல. ஒவ்வொரு namespace-க்கும் தனி loopback interface உண்டு; புதிதாக உருவாக்கும்போது அது down நிலையில் இருக்கும். Process ஒரு network சூழலில் இயங்கி அதன் interfaces, routes-ஐப் பார்க்கிறது. Namespace network தனிமையும் filesystem தனிமையும் வேறு; application கோப்புகளைப் பகிர்ந்தபடியே வேறு network-ஐப் பார்க்கலாம்.'}},
      {heading:{en:'Veth, bridges, and routed paths',ta:'Veth, bridges மற்றும் routed paths'},body:{en:'A veth pair behaves like a virtual cable: traffic transmitted on one endpoint arrives at its peer. Moving one endpoint into each namespace connects the stacks without involving a physical uplink. A Linux bridge can connect several endpoints at layer 2; assigning different subnets and forwarding between them introduces routing. Internet access would require additional routes and possibly forwarding, policy, and NAT, none of which this direct-link lab enables. A local ping therefore tests the virtual link, not an Internet gateway.',ta:'Veth pair ஒரு virtual cable போல இயங்குகிறது; ஒரு endpoint அனுப்புவது peer-இல் கிடைக்கும். ஒவ்வொரு namespace-க்கும் ஒரு endpoint நகர்த்தினால் physical uplink இல்லாமல் stacks இணையும். Linux bridge பல endpoints-ஐ layer 2-இல் இணைக்கலாம். வெவ்வேறு subnets ஒதுக்கி அவற்றிடையே அனுப்புவது routing-ஐச் சேர்க்கிறது. Internet அணுக கூடுதல் routes, forwarding, policy, சில சூழலில் NAT தேவை; இந்த நேரடி-link lab அவற்றை enable செய்யாது. எனவே local ping virtual link-ஐச் சோதிக்கிறது; Internet gateway-ஐ அல்ல.'}},
      {heading:{en:'Containers and lifecycle discipline',ta:'Containers மற்றும் lifecycle ஒழுங்கு'},body:{en:'Container systems compose namespaces with other isolation and resource mechanisms. Kubernetes Pod networking and Service virtual addresses depend on the deployed network implementation; a Service address is not simply another name for a Pod interface. NetworkPolicy enforcement also requires implementation support. Deleting a named namespace removes its name, but processes or other references can keep the network context alive. Use unique experiment names, avoid long-running processes, and remove only resources created by the exercise so another person’s lab is not accidentally destroyed.',ta:'Container systems namespaces உடன் பிற isolation, resource முறைகளை இணைக்கின்றன. Kubernetes Pod networking, Service virtual addresses ஆகியவை பயன்படுத்திய network implementation-ஐச் சாரும். Service address என்பது Pod interface-க்கான மற்றொரு பெயர் மட்டும் அல்ல. NetworkPolicy அமலாக்கத்திற்கும் implementation ஆதரவு தேவை. பெயருள்ள namespace-ஐ நீக்குவது அதன் பெயரை அகற்றும்; processes அல்லது பிற references சூழலை உயிரோடு வைத்திருக்கலாம். தனிப்பட்ட பெயர்கள் பயன்படுத்தி நீண்டநாள் processes தவிர்த்து, இந்தப் பயிற்சி உருவாக்கிய resources மட்டும் அகற்ற வேண்டும்; பிறரின் lab அழியக் கூடாது.'}}
    ],
    example:{en:'Namespace A owns 10.203.0.1/30 and namespace B owns 10.203.0.2/30 on opposite veth ends. Both addresses belong to 10.203.0.0/30, so each uses a connected route and resolves its peer directly. No default route or NAT is needed for the ping, and the host’s main routing table need not change.',ta:'Namespace A-க்கு 10.203.0.1/30, B-க்கு 10.203.0.2/30 எதிரெதிர் veth முனைகளில் உள்ளன. இரண்டும் 10.203.0.0/30-க்குள் வருவதால் connected route கொண்டு peer-ஐ நேரடியாகத் தீர்மானிக்கின்றன. Ping-க்கு default route அல்லது NAT தேவையில்லை; host main routing table-மும் மாற வேண்டியதில்லை.'},
    failure:{en:'Addresses look correct but ping fails because one veth endpoint remains down. Check link state inside both namespaces, prefix lengths, and neighbor entries. Do not enable host forwarding as a reflex: these two peers share a direct link and do not require the host to route between them.',ta:'Addresses சரியாக இருந்தும் ஒரு veth முனை down என்பதால் ping தோல்வியடைகிறது. இரு namespaces-க்குள்ளும் link state, prefix length, neighbor entries பாருங்கள். உடனே host forwarding enable செய்ய வேண்டாம்; இந்த peers நேரடியாக இணைந்ததால் host routing தேவையில்லை.'},
    lab:{commands:'bash <<\'SH\'\nset -e\nlab_tag="cb28-$$"\na="${lab_tag}-a"\nb="${lab_tag}-b"\nmade_a=0\nmade_b=0\ncleanup() {\n  if [ "$made_a" = 1 ]; then sudo ip netns del "$a"; fi\n  if [ "$made_b" = 1 ]; then sudo ip netns del "$b"; fi\n}\ntrap cleanup EXIT\nsudo ip netns add "$a"\nmade_a=1\nsudo ip netns add "$b"\nmade_b=1\nsudo ip -n "$a" link add va type veth peer name vb\nsudo ip -n "$a" link set vb netns "$b"\nsudo ip -n "$a" addr add 10.203.0.1/30 dev va\nsudo ip -n "$b" addr add 10.203.0.2/30 dev vb\nsudo ip -n "$a" link set lo up\nsudo ip -n "$b" link set lo up\nsudo ip -n "$a" link set va up\nsudo ip -n "$b" link set vb up\nsudo ip -n "$a" route show\nsudo ip netns exec "$a" ping -c 3 -W 1 10.203.0.2\nSH',guidance:{en:'Requires Linux, bash, iproute2, ping, and permission to create namespaces. Run the complete block in a disposable development environment. Names incorporate the shell PID; creation flags ensure automatic cleanup targets only namespaces successfully created by this run.',ta:'Linux, bash, iproute2, ping, namespace உருவாக்கும் அனுமதி தேவை. தற்காலிக development சூழலில் முழு block-ஐ இயக்குங்கள். பெயர்களில் shell PID சேர்கிறது; இந்த run வெற்றியாக உருவாக்கிய namespaces மட்டும் cleanup செய்ய creation flags உதவுகின்றன.'},expected:{en:'A connected /30 route and three replies appear. Restricted containers may reject namespace operations; report that capability limit without changing host security settings.',ta:'Connected /30 route மற்றும் மூன்று replies கிடைக்கும். கட்டுப்படுத்தப்பட்ட containers namespace செயல்களை மறுக்கலாம்; host பாதுகாப்பை மாற்றாமல் அந்த capability வரம்பைப் பதிவு செய்யுங்கள்.'},cleanup:{en:'The EXIT trap deletes the two created namespaces and their veth link on normal completion or command failure. No background processes are started. After an uncatchable termination, inspect ip netns list and remove only the exact names printed or identified for this run.',ta:'சாதாரண முடிவிலோ command தோல்வியிலோ EXIT trap உருவாக்கிய இரண்டு namespaces மற்றும் veth link-ஐ அகற்றும். Background processes தொடங்கப்படவில்லை. பிடிக்கமுடியாத termination ஏற்பட்டால் ip netns list பார்த்து இந்த run-க்கான சரியான பெயர்களை மட்டும் அடையாளம் கண்டு அகற்றுங்கள்.'}},
    questions:[
      {question:{en:'Does a network namespace create a separate kernel?',ta:'Network namespace தனி kernel உருவாக்குமா?'},options:{en:['No; network contexts share the kernel','Yes; one kernel per interface','Only when ping runs'],ta:['இல்லை; network சூழல்கள் kernel-ஐப் பகிர்கின்றன','ஆம்; interface ஒன்றுக்கு kernel ஒன்று','Ping இயங்கும்போது மட்டும்']},answer:0,explanation:{en:'Namespace isolation is a kernel feature, not hardware virtualization.',ta:'Namespace isolation kernel வசதி; hardware virtualization அல்ல.'}},
      {question:{en:'Why can 10.203.0.1/30 reach 10.203.0.2/30 without a default route?',ta:'Default route இல்லாமல் 10.203.0.1/30 எப்படி 10.203.0.2/30-ஐ அணுகும்?'},options:{en:['Both use the same connected subnet','NAT is automatically enabled','DNS supplies a route'],ta:['இரண்டும் ஒரே connected subnet-இல் உள்ளன','NAT தானாக enable ஆகிறது','DNS route தருகிறது']},answer:0,explanation:{en:'The on-link route is sufficient for this direct peer.',ta:'இந்த நேரடி peer-க்கு on-link route போதுமானது.'}},
      {question:{en:'Why can a deleted namespace remain alive?',ta:'பெயர் நீக்கிய namespace ஏன் இன்னும் உயிருடன் இருக்கலாம்?'},options:{en:['A process or reference still holds it','ARP recreates every namespace','Its name can never be deleted'],ta:['Process அல்லது reference அதை இன்னும் வைத்திருக்கிறது','ARP எல்லா namespaces-ஐயும் மீண்டும் உருவாக்குகிறது','அதன் பெயரை நீக்கவே முடியாது']},answer:0,explanation:{en:'Removing the name and releasing every reference are different lifecycle events.',ta:'பெயரை நீக்குவதும் எல்லா references-ஐயும் விடுவிப்பதும் வேறு lifecycle நிகழ்வுகள்.'}}
    ],refs:[['Network namespaces manual','https://man7.org/linux/man-pages/man7/network_namespaces.7.html'],['ip-netns manual','https://man7.org/linux/man-pages/man8/ip-netns.8.html'],['Kubernetes network policies','https://kubernetes.io/docs/concepts/services-networking/network-policies/']]
  },
  {
    id:29,module:7,model:'framing',title:{en:'Measure performance & build a socket app',ta:'செயல்திறன் அளவீடும் socket app உருவாக்கமும்'},
    summary:{en:'Implement explicit TCP message framing and measure useful delivery with clear scope and units.',ta:'TCP message framing-ஐ வெளிப்படையாக உருவாக்கி பயனுள்ள வழங்கலைத் தெளிவான அளவீட்டு வரம்பு மற்றும் அலகுகளுடன் அளவிடுங்கள்.'},
    prerequisites:{en:'Understand TCP byte streams, Python bytes, loops, exceptions, and basic throughput units.',ta:'TCP byte stream, Python bytes, loops, exceptions, அடிப்படை throughput அலகுகள் ஆகியவை தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Handle partial reads and bounded message lengths.','Distinguish accepted writes from application delivery.','Compute goodput and document benchmark limitations.'],ta:['Partial reads மற்றும் வரம்பிட்ட message length-ஐக் கையாளுதல்.','Write ஏற்கப்பட்டது மற்றும் application delivery வேறுபாட்டை விளக்குதல்.','Goodput கணக்கிட்டு benchmark வரம்புகளை ஆவணப்படுத்துதல்.']},
    sections:[
      {heading:{en:'TCP needs application framing',ta:'TCP-க்கு application framing தேவை'},body:{en:'TCP exposes an ordered byte stream, not preserved messages. One send can require several receives, and several sends can arrive in one receive. Define a framing rule such as a four-byte unsigned network-order length followed by exactly that many payload bytes. Read the entire header before interpreting it, enforce a maximum before allocating payload storage, and accumulate bytes until the frame is complete. Decide explicitly whether zero-length messages are valid. Encoding text also requires agreement on a character encoding such as UTF-8.',ta:'TCP வரிசைப்படுத்திய byte stream தருகிறது; message எல்லைகளைப் பாதுகாப்பதில்லை. ஒரு send-க்கு பல receives தேவைப்படலாம்; பல sends ஒரே receive-இல் வரலாம். நான்கு-byte unsigned network-order length, அதன் பின் குறிப்பிட்ட அளவு payload என்று framing விதி அமைக்கலாம். Header முழுவதையும் படித்தபின் விளக்கி, payload இடம் ஒதுக்குமுன் அதிகபட்ச வரம்பைச் சோதித்து, frame முடியும் வரை bytes சேர்க்க வேண்டும். Zero-length message செல்லுமா என்பதைத் தெளிவாக முடிவு செய்யுங்கள். Text-க்கு UTF-8 போன்ற character encoding-யும் ஒத்துப்போக வேண்டும்.'}},
      {heading:{en:'Errors, deadlines, and resource limits',ta:'பிழைகள், நேரக்கெடு மற்றும் resource வரம்புகள்'},body:{en:'A receive returning empty bytes signals end-of-stream; if a frame is incomplete, treat it as truncated rather than a valid short message. Python sendall handles repeated writes but does not prove that the remote application processed the data. Timeouts prevent indefinite waits, although a total frame deadline may require tracking elapsed time across calls. Bound message sizes, concurrent clients, and buffered output to prevent resource exhaustion. Authentication and TLS are additional requirements before extending an educational loopback protocol to an untrusted network.',ta:'Receive empty bytes தருவது end-of-stream. Frame முடியாவிட்டால் அதைச் சரியான குறுகிய message என்று ஏற்காமல் truncated எனக் கருத வேண்டும். Python sendall மீண்டும் writes செய்வதைக் கையாளும்; remote application செயலாக்கியது என்று நிரூபிக்காது. Timeouts முடிவற்ற காத்திருப்பைத் தடுக்கும்; முழு frame deadline-க்கு calls இடையே கடந்த நேரத்தைக் கணக்கிட வேண்டியிருக்கலாம். Resource exhaustion தவிர்க்க message அளவு, concurrent clients, buffered output வரம்பிடுங்கள். கல்விக்கான loopback protocol-ஐ நம்பாத network-க்கு விரிவாக்குமுன் authentication மற்றும் TLS கூடுதல் தேவைகள்.'}},
      {heading:{en:'Measure the intended workload',ta:'நோக்கமுள்ள workload-ஐ அளவிடுதல்'},body:{en:'Goodput counts useful application bytes delivered per elapsed time, excluding framing and retransmitted transport bytes. Use a monotonic clock for durations and report decimal MB/s separately from Mbit/s. Define whether setup, encryption, disk access, and application acknowledgments are included. Loopback exercises framing and local scheduling; it cannot estimate Wi-Fi capacity or wide-area loss response. Tools such as iperf3 isolate transport behavior, whereas an actual file service includes more dependencies. Repeat comparable runs and retain raw results rather than selecting only the fastest observation.',ta:'Goodput என்பது கடந்த நேரத்தில் வழங்கப்பட்ட பயனுள்ள application bytes; framing மற்றும் மீண்டும் அனுப்பிய transport bytes இதில் சேராது. Duration-க்கு monotonic clock பயன்படுத்தி decimal MB/s, Mbit/s தனித்தனியாகக் கூறுங்கள். Setup, encryption, disk அணுகல், application acknowledgments சேருமா என்று வரையறுக்க வேண்டும். Loopback framing மற்றும் local scheduling-ஐச் சோதிக்கும்; Wi-Fi capacity அல்லது தொலைப்பாதை loss response-ஐ மதிப்பிடாது. Iperf3 போன்றவை transport செயல்பாட்டைத் தனியாகக் காட்டும்; உண்மையான file service-க்கு மேலும் dependencies உண்டு. ஒப்பிடத்தக்க runs மீண்டும் செய்து வேகமான ஒன்றை மட்டும் தேர்ந்தெடுக்காமல் raw முடிவுகளை வைத்திருங்கள்.'}}
    ],
    example:{en:'A transfer delivers 12,000,000 useful bytes in 3 seconds. Goodput is 4,000,000 bytes/s = 4 MB/s = 32 Mbit/s. A four-byte header per message increases wire traffic without increasing useful payload. Measuring only the sender’s sendall duration can overstate delivery speed because the kernel may buffer unsent bytes.',ta:'12,000,000 பயனுள்ள bytes 3 வினாடிகளில் வழங்கப்பட்டால் goodput 4,000,000 bytes/s = 4 MB/s = 32 Mbit/s. Message ஒன்றுக்கு நான்கு-byte header wire traffic-ஐ அதிகரிக்கும்; useful payload-ஐ அல்ல. Kernel அனுப்பாத bytes-ஐ buffer செய்யலாம் என்பதால் sender sendall நேரம் மட்டும் delivery வேகத்தை அதிகமாகக் காட்டலாம்.'},
    failure:{en:'An implementation reads the length with one recv(4) and occasionally crashes under load. TCP may return fewer than four bytes without error. Replace the assumption with an exact-read loop, then test truncated headers, oversized lengths, and multiple frames in one stream; changing TCP segment size would not repair framing.',ta:'Implementation ஒரே recv(4) மூலம் length படிக்கிறது; load-இல் சில நேரங்களில் crash ஆகிறது. பிழையின்றி TCP நான்குக்கும் குறைவான bytes தரலாம். Exact-read loop பயன்படுத்தி truncated header, அதிக length, ஒரே stream-இல் பல frames ஆகியவற்றைச் சோதிக்க வேண்டும்; TCP segment அளவு மாற்றுவது framing-ஐச் சரிசெய்யாது.'},
    lab:{commands:'python3 - <<\'PY\'\nimport socket, struct\nfrom concurrent.futures import ThreadPoolExecutor\n\ndef exact(s, n):\n    data = bytearray()\n    while len(data) < n:\n        part = s.recv(min(n - len(data), 2))\n        if not part:\n            raise EOFError("truncated frame")\n        data.extend(part)\n    return bytes(data)\n\ndef receive(s):\n    n = struct.unpack("!I", exact(s, 4))[0]\n    if n > 1024:\n        raise ValueError("oversized frame")\n    return exact(s, n)\n\nwith socket.socket() as listener:\n    listener.bind(("127.0.0.1", 0))\n    listener.listen(1)\n    listener.settimeout(3)\n    with socket.create_connection(listener.getsockname(), timeout=3) as sender:\n        receiver, _ = listener.accept()\n        with receiver, ThreadPoolExecutor(max_workers=1) as pool:\n            receiver.settimeout(3)\n            result = pool.submit(receive, receiver)\n            payload = "vanakkam".encode("utf-8")\n            sender.sendall(struct.pack("!I", len(payload)) + payload)\n            sender.shutdown(socket.SHUT_WR)\n            print(result.result(timeout=4).decode("utf-8"))\nPY',guidance:{en:'Python 3 uses a loopback-only ephemeral TCP listener. The receiver deliberately requests at most two bytes per read to exercise accumulation without assuming any particular packet segmentation. This is a framing demonstration, not a benchmark or production server.',ta:'Python 3 loopback மட்டும் பயன்படுத்தும் தற்காலிக TCP port-இல் கேட்கிறது. குறிப்பிட்ட packet segmentation-ஐ ஊகிக்காமல் bytes சேர்ப்பைச் சோதிக்க receiver ஒவ்வொரு read-க்கும் அதிகபட்சம் இரண்டு bytes கேட்கிறது. இது framing விளக்கம்; benchmark அல்லது production server அல்ல.'},expected:{en:'The complete payload vanakkam is printed despite reads smaller than the header. The length limit is checked before reading the payload; EOF during a required read raises an error.',ta:'Header-ஐவிடச் சிறிய reads இருந்தாலும் முழு vanakkam அச்சிடப்படும். Payload படிக்குமுன் length வரம்பு சோதிக்கப்படுகிறது; தேவையான read நடுவில் EOF வந்தால் error எழும்.'},cleanup:{en:'Context managers close all sockets and the worker. No files or persistent listeners remain after completion.',ta:'Context managers எல்லா sockets மற்றும் worker-ஐ முடிக்கின்றன. முடிந்தபின் கோப்புகளோ நிரந்தர listeners-ஓ இல்லை.'}},
    questions:[
      {question:{en:'What does one successful recv(4) guarantee?',ta:'வெற்றியான ஒரே recv(4) எதை உறுதி செய்கிறது?'},options:{en:['At most four bytes, possibly fewer','Exactly one application message','Exactly four bytes always'],ta:['அதிகபட்சம் நான்கு bytes; குறைவாகவும் இருக்கலாம்','சரியாக ஒரு application message','எப்போதும் சரியாக நான்கு bytes']},answer:0,explanation:{en:'The argument bounds returned bytes; framing must accumulate the required amount.',ta:'Argument திரும்பும் bytes-ஐ வரம்பிடுகிறது; தேவையான அளவை framing சேர்க்க வேண்டும்.'}},
      {question:{en:'8,000,000 useful bytes in 2 seconds equals what goodput?',ta:'8,000,000 useful bytes 2 வினாடிகளில் வந்தால் goodput என்ன?'},options:{en:['4 MB/s or 32 Mbit/s','8 MB/s or 8 Mbit/s','32 MB/s'],ta:['4 MB/s அல்லது 32 Mbit/s','8 MB/s அல்லது 8 Mbit/s','32 MB/s']},answer:0,explanation:{en:'Divide by two seconds, then multiply bytes/s by eight for bits/s.',ta:'இரண்டு வினாடிகளால் வகுத்து bytes/s-ஐ எட்டால் பெருக்கினால் bits/s கிடைக்கும்.'}},
      {question:{en:'EOF arrives after two bytes of a required four-byte header. What should happen?',ta:'தேவையான நான்கு-byte header-இல் இரண்டு bytes-க்குப் பின் EOF. என்ன செய்ய வேண்டும்?'},options:{en:['Reject a truncated frame','Interpret missing bytes as zeros','Treat it as a complete empty message'],ta:['Truncated frame என்று நிராகரிக்க வேண்டும்','இல்லாத bytes-ஐ zeros எனக் கொள்ள வேண்டும்','முழுமையான empty message என ஏற்க வேண்டும்']},answer:0,explanation:{en:'Incomplete framing cannot safely specify the payload.',ta:'முழுமையற்ற framing payload-ஐப் பாதுகாப்பாகக் குறிப்பிட முடியாது.'}}
    ],refs:[['Python socket HOWTO','https://docs.python.org/3/howto/sockets.html'],['Python socket API','https://docs.python.org/3/library/socket.html'],['iperf3 documentation','https://software.es.net/iperf/'],['TCP — RFC 9293','https://www.rfc-editor.org/rfc/rfc9293.html']]
  },
  {
    id:30,module:7,model:'research',title:{en:'Read RFCs & design an expert capstone',ta:'RFC வாசிப்பும் ஆதாரமுள்ள capstone வடிவமைப்பும்'},
    summary:{en:'Combine standards, controlled experiments, uncertainty, reproducible artifacts, and prior-work checks into defensible claims.',ta:'Standards, கட்டுப்படுத்திய ஆய்வுகள், நிச்சயமின்மை, மீளுருவாக்க ஆவணங்கள், முந்தைய ஆய்வு சோதனைகள் ஆகியவற்றை இணைத்து ஆதாரமுள்ள முடிவுகளை உருவாக்குங்கள்.'},
    prerequisites:{en:'Understand protocol layers, routing and security policy, goodput, basic averages, and controlled Linux experiments.',ta:'Protocol layers, routing, security policy, goodput, அடிப்படை சராசரி, கட்டுப்படுத்திய Linux ஆய்வுகள் ஆகியவை புரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Read specification status, normative requirements, updates, and errata.','Design repeatable comparisons and interpret variance and confidence intervals.','Check novelty and publish bounded claims with reproducible evidence.'],ta:['Specification நிலை, normative requirements, updates, errata வாசித்தல்.','மீண்டும் செய்யக்கூடிய ஒப்பீடுகளை வடிவமைத்து variance, confidence intervals விளக்குதல்.','புதுமையைச் சரிபார்த்து மீளுருவாக்க ஆதாரத்துடன் வரம்புள்ள முடிவுகளை வழங்குதல்.']},
    sections:[
      {heading:{en:'Standards and a scoped capstone',ta:'Standards மற்றும் வரம்பிட்ட capstone'},body:{en:'An RFC number is not a guarantee of current standards-track status. Inspect its information page, updates, obsoleted relationships, and errata; distinguish normative requirements from examples and implementation choices. For a capstone, specify user, guest, and service segments, address plans, DNS/DHCP roles, IPv6 assumptions, and least-privilege access. Write acceptance tests for permitted and denied flows, name resolution, recovery, path MTU, and a framed socket application. Tie each test to a requirement and identify simplifications rather than presenting the design as universal expertise.',ta:'RFC எண் இருப்பது மட்டும் தற்போதைய standards-track நிலையை உறுதி செய்யாது. Information page, updates, எதை மாற்றியது, errata ஆகியவற்றைப் பாருங்கள். Normative தேவைகள், எடுத்துக்காட்டுகள், implementation தேர்வுகளை வேறுபடுத்துங்கள். Capstone-இல் user, guest, service பகுதிகள், address திட்டம், DNS/DHCP பணிகள், IPv6 ஊகங்கள், குறைந்த உரிமை அணுகல் ஆகியவற்றைக் குறிப்பிடுங்கள். அனுமதி மற்றும் மறுப்பு flows, பெயர் தீர்மானம், recovery, path MTU, framed socket application ஆகியவற்றுக்கு acceptance tests எழுதுங்கள். ஒவ்வொரு test-ஐயும் தேவையுடன் இணைத்து எளிமைப்படுத்தல்களைச் சொல்லுங்கள்; எல்லாச் சூழலுக்கும் முழு நிபுணத்துவம் என்று காட்ட வேண்டாம்.'}},
      {heading:{en:'Statistical experiments and uncertainty',ta:'புள்ளியியல் ஆய்வுகளும் நிச்சயமின்மையும்'},body:{en:'State a measurable hypothesis and primary metric before collecting results. Control workload, topology, software versions, warm-up, cache state, duration, and competing traffic. Randomize or interleave treatment order to reduce time-of-day bias. Repeat independent runs; thousands of correlated packets in one run are not thousands of independent experiments. Sample variance describes dispersion and standard error describes uncertainty in an estimated mean. For independent approximately normal run measurements, a t interval uses mean ± t-critical × s/√n. A 95% confidence procedure covers the fixed population mean in 95% of repeated experiments under its assumptions; it does not contain 95% of individual observations.',ta:'முடிவுகள் சேகரிக்குமுன் அளவிடக்கூடிய கருதுகோளையும் முதன்மை metric-ஐயும் கூறுங்கள். Workload, topology, software version, warm-up, cache நிலை, duration, போட்டி traffic ஆகியவற்றைக் கட்டுப்படுத்துங்கள். நேரத்தால் வரும் சாய்வைக் குறைக்க treatment வரிசையை randomize அல்லது interleave செய்யுங்கள். தனித்தனி runs மீண்டும் செய்ய வேண்டும்; ஒரே run-இன் ஆயிரம் தொடர்புள்ள packets ஆயிரம் சுயாதீன ஆய்வுகள் அல்ல. Sample variance பரவலைக் காட்டும்; standard error மதிப்பிட்ட சராசரியின் நிச்சயமின்மையைக் காட்டும். தனித்தனி, தோராயமாக normal run அளவுகளுக்கு t interval: mean ± t-critical × s/√n. அதன் ஊகங்களில் ஆய்வை மீண்டும் செய்தால் 95% intervals நிலையான population mean-ஐ உள்ளடக்கும்; தனி observations-இல் 95% இதில் இருக்கும் என்பதல்ல.'}},
      {heading:{en:'Reproducibility and novelty checks',ta:'மீளுருவாக்கமும் புதுமைச் சோதனையும்'},body:{en:'Retain raw measurements, scripts, dependency versions, topology, seeds where used, configuration, and sanitized traces. Record excluded runs and reasons before inspecting whether exclusion improves the result. Report effect sizes, uncertainty, failures, and limits of generalization. For novelty, search relevant RFCs, Internet-Drafts, original papers, and implementation documentation using both your term and established synonyms. Compare the closest methods and reproduce a baseline before claiming improvement. A new classroom implementation can be a valuable learning result without being a new research contribution; novelty requires explaining what differs from prior work.',ta:'Raw measurements, scripts, dependency versions, topology, பயன்படுத்திய seeds, configuration, ரகசியங்கள் நீக்கிய traces ஆகியவற்றை வைத்திருங்கள். Run நீக்குவதற்கான காரணத்தை அது முடிவை மேம்படுத்துகிறதா என்று பார்ப்பதற்கு முன்பே பதிவு செய்யுங்கள். Effect size, நிச்சயமின்மை, failures, பொதுமைப்படுத்தலின் வரம்புகள் கூறப்பட வேண்டும். புதுமைக்கு உங்கள் சொற்களும் வழக்கிலுள்ள இணைச் சொற்களும் கொண்டு தொடர்புடைய RFCs, Internet-Drafts, அசல் ஆய்வுக் கட்டுரைகள், implementation documentation தேடுங்கள். அருகிலுள்ள முறைகளை ஒப்பிட்டு மேம்பாடு கூறுமுன் baseline-ஐ மீளுருவாக்குங்கள். புதிய classroom implementation பயனுள்ள கற்றல் விளைவாக இருக்கலாம்; புதிய research contribution ஆக வேண்டியதில்லை. முந்தைய பணியிலிருந்து என்ன வேறுபடுகிறது என்று விளக்கினால்தான் புதுமைக் கோரிக்கை வலுப்பெறும்.'}}
    ],
    example:{en:'Five independent goodput runs are 90, 92, 94, 96, and 98 Mbit/s. Mean is 94, sample variance is 10, and s is about 3.162. Standard error is about 1.414. With t-critical 2.776 for four degrees of freedom, the illustrative 95% mean interval is approximately [90.07, 97.93] Mbit/s. This calculation depends on the sampling assumptions and does not establish superiority over an unmeasured baseline.',ta:'சுயாதீனமான ஐந்து goodput runs 90, 92, 94, 96, 98 Mbit/s. Mean 94; sample variance 10; s சுமார் 3.162. Standard error சுமார் 1.414. நான்கு degrees of freedom-க்கு t-critical 2.776 பயன்படுத்தினால் விளக்கத்திற்கான 95% mean interval சுமார் [90.07, 97.93] Mbit/s. இந்தக் கணக்கு sampling ஊகங்களைச் சாரும்; அளவிடாத baseline-ஐவிடச் சிறந்தது என்று நிறுவாது.'},
    failure:{en:'A proposed algorithm is tested once after warming its cache, while the baseline is tested cold, and the faster result is called novel. The comparison confounds treatment with cache state and provides no estimate of run variance. Match conditions, interleave repeated runs, inspect prior implementations, and state the remaining uncertainty before making a research claim.',ta:'புதிய algorithm warm cache-இல் ஒருமுறை சோதிக்கப்படுகிறது; baseline cold cache-இல் சோதிக்கப்படுகிறது; வேகமான முடிவு புதுமை எனப்படுகிறது. Treatment மற்றும் cache நிலை கலந்துவிட்டன; run variance மதிப்பீடும் இல்லை. சூழலைச் சமமாக்கி மீள்சோதனைகளை interleave செய்து முந்தைய implementations பாருங்கள்; மீதமுள்ள நிச்சயமின்மையைச் சொல்லியபின் research முடிவு கூறுங்கள்.'},
    lab:{commands:'python3 - <<\'PY\'\nimport math, statistics, sys\nx = [90, 92, 94, 96, 98]\nn = len(x)\nmean = statistics.mean(x)\nvariance = statistics.variance(x)\nse = statistics.stdev(x) / math.sqrt(n)\nmargin = 2.776 * se\nprint("Python", sys.version.split()[0])\nprint("n", n, "mean", mean, "sample_variance", variance, "SE", round(se, 3))\nprint("illustrative_95pct_t_interval", round(mean-margin, 2), round(mean+margin, 2))\nPY\nuname -sr',guidance:{en:'The five values are explicitly synthetic teaching data, not measured network results. The supplied critical value applies only to this five-run, two-sided 95% example. Reproduce the arithmetic, then design a separate measurement plan with raw run data, defined conditions, and an appropriate uncertainty method.',ta:'ஐந்து எண்களும் கற்பித்தலுக்காக உருவாக்கப்பட்டவை; அளந்த network முடிவுகள் அல்ல. கொடுத்த critical value இந்த ஐந்து-run, இருபக்க 95% எடுத்துக்காட்டுக்கு மட்டும் பொருந்தும். கணக்கை மீளுருவாக்கி, பின்னர் raw run data, வரையறுத்த சூழல், பொருத்தமான uncertainty முறை கொண்ட தனி measurement திட்டம் அமைக்குங்கள்.'},expected:{en:'Mean 94, sample variance 10, SE about 1.414, and interval 90.07–97.93 appear. The version output helps document the environment, but reproducibility also requires the experimental setup and data provenance.',ta:'Mean 94, sample variance 10, SE சுமார் 1.414, interval 90.07–97.93 கிடைக்கும். Version வெளியீடு சூழலை ஆவணப்படுத்த உதவும்; மீளுருவாக்கத்திற்கு experimental setup, தரவு வந்த வழி ஆகியவையும் தேவை.'},cleanup:{en:'The arithmetic runs entirely in memory and creates no files or network changes.',ta:'கணக்கு முழுவதும் memory-இல் நடக்கிறது; கோப்புகளோ network மாற்றங்களோ இல்லை.'}},
    questions:[
      {question:{en:'What must be checked before treating an RFC as the current specification?',ta:'RFC-ஐ தற்போதைய specification எனக் கொள்ளுமுன் எதைப் பார்க்க வேண்டும்?'},options:{en:['Status, updates, obsoleted relationships, and errata','Only its number','Only the first example'],ta:['நிலை, updates, மாற்றப்பட்ட தொடர்புகள், errata','எண்ணை மட்டும்','முதல் எடுத்துக்காட்டை மட்டும்']},answer:0,explanation:{en:'Publication alone does not establish present applicability or standards status.',ta:'வெளியீடு மட்டும் தற்போதைய பொருத்தத்தையோ standards நிலையையோ நிறுவாது.'}},
      {question:{en:'With s=4 and n=16 independent runs, what is the estimated standard error of the mean?',ta:'s=4, n=16 சுயாதீன runs எனில் mean-இன் மதிப்பிட்ட standard error என்ன?'},options:{en:['1','4','16'],ta:['1','4','16']},answer:0,explanation:{en:'SE = s/√n = 4/4 = 1; dispersion s and uncertainty in the mean are different quantities.',ta:'SE = s/√n = 4/4 = 1. பரவல் s மற்றும் mean நிச்சயமின்மை வெவ்வேறு அளவுகள்.'}},
      {question:{en:'What best supports a novelty claim?',ta:'புதுமைக் கோரிக்கைக்கு சிறந்த ஆதாரம் எது?'},options:{en:['A documented difference from closest prior work plus reproducible evaluation','A new name for an established technique','One fast run without a baseline'],ta:['அருகிலுள்ள முந்தைய பணியிலிருந்து ஆவணப்படுத்திய வேறுபாடும் மீளுருவாக்க மதிப்பீடும்','பழைய நுட்பத்திற்குப் புதிய பெயர்','Baseline இல்லாத ஒரே வேகமான run']},answer:0,explanation:{en:'Novelty concerns prior knowledge, while evaluation supports the claimed practical effect.',ta:'புதுமை முந்தைய அறிவுடன் ஒப்பிடப்படுகிறது; மதிப்பீடு கூறப்படும் நடைமுறை விளைவுக்கு ஆதாரம் தருகிறது.'}}
    ],refs:[['IETF standards process — RFC 2026','https://www.rfc-editor.org/rfc/rfc2026.html'],['RFC status and errata','https://www.rfc-editor.org/'],['NIST confidence limits for a mean','https://www.itl.nist.gov/div898/handbook/eda/section3/eda352.htm'],['IP performance metrics framework — RFC 2330','https://www.rfc-editor.org/rfc/rfc2330.html']]
  }
];
